{"path": "packages/core/src/types.ts", "start_line": 1, "end_line": 153, "total_lines": 153, "content": "     1	import type { Price, Quote } from './amounts.js';
     2	
     3	/** A string constrained to a valid absolute URL at construction. */
     4	export type UrlString = string & { readonly __brand: 'UrlString' };
     5	
     6	export function url(value: string): UrlString {
     7	  try {
     8	    return new URL(value) as unknown as UrlString;
     9	  } catch (cause) {
    10	    throw new TypeError(`url(): invalid absolute URL: ${value}`, { cause });
    11	  }
    12	}
    13	
    14	export type HeaderRecord = Record<string, string>;
    15	
    16	/**
    17	 * The three distinct failure classes. Today's agents collapse all of these
    18	 * into a generic fetch failure; the broker reports each separately so the
    19	 * cost decision is visible.
    20	 */
    21	export type FailureClass = 'blocked' | 'payment-required' | 'token-rejected';
    22	
    23	export type FetchStatus = 'fulfilled' | 'denied' | 'error';
    24	
    25	export interface FetchParams {
    26	  url: UrlString;
    27	  headers?: HeaderRecord;
    28	  /** Optional tenant/subject for multi-tenant accounting. */
    29	  tenantId?: string;
    30	  /** Extra budget context from the caller, merged under broker policy. */
    31	  budgetOverride?: { perCallCeilingMicros?: number; lineItemCeilingMicros?: number };
    32	}
    33	
    34	export type RslClauseType =
    35	  | 'attribution'
    36	  | 'no-store'
    37	  | 'no-derivative-works'
    38	  | 'no-commercial-use'
    39	  | 'pay-per-inference'
    40	  | 'redistribution'
    41	  | (string & {});
    42	
    43	export type RslClauseValue = 'required' | 'permitted' | 'forbidden' | number;
    44	
    45	export interface RslClause {
    46	  type: string;
    47	  value: RslClauseValue;
    48	  params: Record<string, string | number>;
    49	}
    50	
    51	/** A parsed Rights Statement Language (RSL) document. */
    52	export interface License {
    53	  draft: string;
    54	  id: string;
    55	  title?: string;
    56	  publishedAt?: string;
    57	  clauses: RslClause[];
    58	  rawSource: string;
    59	}
    60	
    61	/**
    62	 * Obligations the broker derives from a license and enforces/surfaces for
    63	 * this particular fetch. Surfaced in the outcome so the caller can comply.
    64	 */
    65	export interface LicenseObligation {
    66	  clause: string;
    67	  kind: 'notice' | 'store-prohibited' | 'inference-budget' | 'forbidden' | 'permitted';
    68	  instruction: string;
    69	  applied?: string;
    70	}
    71	
    72	export interface IdentityPresentation {
    73	  keyId: string;
    74	  algorithm: 'ed25519';
    75	  signedHeaders: string[];
    76	  timestamp: string;
    77	  /** Opaque PACT-style attestation token where the origin accepts one. */
    78	  pactToken?: string;
    79	}
    80	
    81	export interface FetchOutcome {
    82	  fetchId: string;
    83	  status: FetchStatus;
    84	  /** Present iff status !== 'fulfilled'. The three distinct failure classes. */
    85	  failureClass?: FailureClass;
    86	  reason: string;
    87	  origin?: { url: string; httpStatus?: number };
    88	  content?: { body: string; contentType: string; storeable: boolean; attributionNotice?: string };
    89	  license?: License;
    90	  obligations?: LicenseObligation[];
    91	  price?: Price;
    92	  quote?: Quote;
    93	  rail?: string;
    94	  settlementRef?: string;
    95	  identity?: IdentityPresentation;
    96	  tenantId?: string;
    97	  timestamps: { startedAt: string; completedAt: string };
    98	  error?: { code: string; message: string };
    99	}
   100	
   101	/** A raw ledger row — the audit surface. */
   102	export interface LedgerEntry {
   103	  seq: number;
   104	  fetchId: string;
   105	  tenantId: string;
   106	  url: string;
   107	  status: FetchStatus;
   108	  failureClass?: FailureClass;
   109	  httpStatus?: number;
   110	  priceMicros?: number;
   111	  currency?: string;
   112	  rail?: string;
   113	  licenseId?: string;
   114	  keyId?: string;
   115	  settlementRef?: string;
   116	  startedAt: string;
   117	  completedAt: string;
   118	  recordedAt: string;
   119	}
   120	
   121	/**
   122	 * A payment rail: one interface, pluggable backends.
   123	 * Backends: x402 facilitator, Cloudflare Pay Per Crawl, self-hosted 402.
   124	 * The interface is stable; backend field names are not (draft-caveat discipline).
   125	 */
   126	export interface PaymentRequest {
   127	  url: UrlString;
   128	  method: string;
   129	  headers: HeaderRecord;
   130	  contentType?: string;
   131	}
   132	
   133	export interface RailAuthorization {
   134	  /** Headers the origin expects on the settled request (e.g. X-PAYMENT). */
   135	  settlementHeaders: HeaderRecord;
   136	  scheme: string;
   137	  payload: string;
   138	}
   139	
   140	export interface RailSettlement {
   141	  rail: string;
   142	  settlementRef: string;
   143	  amountMicros: number;
   144	  currency: string;
   145	  settledAt: string;
   146	}
   147	
   148	export interface PaymentRail {
   149	  readonly id: string;
   150	  quote(req: PaymentRequest): Promise<Quote>;
   151	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization>;
   152	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement>;
   153	}"}

{"path": "packages/core/src/amounts.ts", "start_line": 1, "end_line": 36, "total_lines": 36, "content": "     1	/**
     2	 * Money as integer micro-units (1/1,000,000 of a currency unit), like x402.
     3	 * Avoids floating point in anything that touches a ceiling or a ledger.
     4	 */
     5	export type Micros = number;
     6	
     7	export const MICRO_PER_UNIT = 1_000_000;
     8	
     9	export interface Price {
    10	  unitsMicros: number;
    11	  currency: string;
    12	}
    13	
    14	export interface Quote extends Price {
    15	  rail: string;
    16	  settlement: 'immediate' | 'batch';
    17	  expiresAt?: string;
    18	}
    19	
    20	export function micros(units: number): Micros {
    21	  if (!Number.isFinite(units)) throw new RangeError(`micros(): non-finite unit value ${units}`);
    22	  const v = Math.round(units * MICRO_PER_UNIT);
    23	  if (!Number.isSafeInteger(v)) throw new RangeError(`micros(): precision overflow for ${units}`);
    24	  return v;
    25	}
    26	
    27	export function formatMicros(micros_: Micros, currency = 'USD'): string {
    28	  return `${(micros_ / MICRO_PER_UNIT).toFixed(2)} ${currency}`;
    29	}
    30	
    31	export function addMicros(a: Micros, b: Micros): Micros {
    32	  if (!Number.isSafeInteger(a) || !Number.isSafeInteger(b)) {
    33	    throw new RangeError('addMicros(): unsafe integer input');
    34	  }
    35	  return a + b;
    36	}"}

{"path": "packages/budget/src/engine.ts", "start_line": 1, "end_line": 230, "total_lines": 230, "content": "     1	import { BudgetError, type Clock, type Micros, type Price, type UrlString } from '@mwb/core';
     2	import {
     3	  defaultPolicy,
     4	  matchLineItem,
     5	  type BudgetPolicy,
     6	} from './policy.js';
     7	
     8	/**
     9	 * A meter is the accounting state for a tenant's spend.
    10	 *
    11	 * Buckets:
    12	 *  - per-call  : one-shot check, not persistent here.
    13	 *  - hourly    : rolling 1-hour window for the tenant.
    14	 *  - daily     : rolling 24-hour window for the tenant.
    15	 *  - line-item : per-line-item buckets (daily + lifetime).
    16	 *
    17	 * The engine does not persist by itself. `AuditLedger` (or a durable
    18	 * implementation) persists records and rehydrates buckets if needed.
    19	 */
    20	export interface MeterState {
    21	  tenantId: string;
    22	  hourly: { windowStart: number; spentMicros: Micros };
    23	  daily: { windowStart: number; spentMicros: Micros };
    24	  lineItems: Record<string, { dailyMicros: number; lifetimeMicros: number }>;
    25	}
    26	
    27	export function emptyMeter(tenantId: string, clock: Clock): MeterState {
    28	  return {
    29	    tenantId,
    30	    hourly: { windowStart: Date.parse(clock.now()), spentMicros: 0 },
    31	    daily: { windowStart: Date.parse(clock.now()), spentMicros: 0 },
    32	    lineItems: {},
    33	  };
    34	}
    35	
    36	interface CheckResult {
    37	  ok: boolean;
    38	  code: string;
    39	  reason: string;
    40	  remainingMicros?: number;
    41	}
    42	
    43	function checkBucket(
    44	  bucketMicros: number,
    45	  ceilingMicros: number,
    46	  priceMicros: number,
    47	  label: string
    48	): CheckResult {
    49	  const remaining = ceilingMicros - bucketMicros;
    50	  if (remaining < 0) return { ok: false, code: 'CEILING_EXCEEDED', reason: `${label}: already over ceiling` };
    51	  if (priceMicros > remaining) {
    52	    return {
    53	      ok: false,
    54	      code: 'PRICE_EXCEEDS_REMAINING',
    55	      reason: `${label}: requested ${priceMicros} exceeds remaining ${remaining}`,
    56	      remainingMicros: remaining,
    57	    };
    58	  }
    59	  return { ok: true, code: 'OK', reason: '', remainingMicros: remaining };
    60	}
    61	
    62	function advanceWindow(
    63	  bucket: { windowStart: number; spentMicros: number },
    64	  nowMs: number,
    65	  windowMs: number
    66	): { windowStart: number; spentMicros: number } {
    67	  if (nowMs - bucket.windowStart >= windowMs) return { windowStart: nowMs, spentMicros: 0 };
    68	  return bucket;
    69	}
    70	
    71	const HOUR_MS = 3_600_000;
    72	const DAY_MS = 86_400_000;
    73	/**
    74	 * The Budget Engine.
    75	 *
    76	 * Responsibilities (and only responsibilities):
    77	 *  1. Refuse work that cannot fit inside a declared ceiling.
    78	 *  2. Record work that has been done (paid or denied) into the meter.
    79	 *  3. Tell the caller exactly which ceiling bit and why.
    80	 *
    81	 * It does NOT decide what to pay with, it does NOT sign anything, it
    82	 * does NOT enforce licenses. Those are the Rail Adapter, Identity, and
    83	 * License Engine. Keeping them separate is what makes each one swappable —
    84	 * which is the whole point of "one contract."
    85	 */
    86	export class BudgetEngine {
    87	  private readonly meters = new Map<string, MeterState>();
    88	  private readonly clock: Clock;
    89	  private readonly policy: BudgetPolicy;
    90	
    91	  constructor(options?: { clock?: Clock; policy?: BudgetPolicy }) {
    92	    this.clock = options?.clock ?? { now: () => new Date().toISOString() };
    93	    this.policy = options?.policy ?? defaultPolicy;
    94	  }
    95	
    96	  get policy(): BudgetPolicy {
    97	    return this.policy;
    98	  }
    99	
   100	  /**
   101	   * Pre-flight: will this request fit?
   102	   *
   103	   * This is the ONLY pre-payment step that may raise BudgetError. The
   104	   * broker surfaces it as `failureClass: 'blocked'` — a policy denial —
   105	   * which the audit layer records as a `denied` row.
   106	   *
   107	   * Deliberately throws (not returns a decision object) because "does not
   108	   * fit" is an exceptional condition for the caller and the audit trail
   109	   * cares about the message, not a tagged union.
   110	   */
   111	  preflight(tenantId: string, price: Price, url?: UrlString): void {
   112	    if (price.currency !== this.policy.currency) {
   113	      throw new BudgetError(
   114	        `Tenant currency mismatch: policy is ${this.policy.currency}, quote is ${price.currency}`,
   115	        'CURRENCY_MISMATCH'
   116	      );
   117	    }
   118	    if (!Number.isSafeInteger(price.unitsMicros) || price.unitsMicros <= 0) {
   119	      throw new BudgetError(`Quote must be a positive safe integer, got ${price.unitsMicros}`, 'BAD_QUOTE');
   120	    }
   121	    if (price.unitsMicros > this.policy.perCallCeilingMicros) {
   122	      throw new BudgetError(
   123	        `Per-call ceiling exceeded: quote ${price.unitsMicros} > ${this.policy.perCallCeilingMicros}`,
   124	        'PER_CALL_CEILING'
   125	      );
   126	    }
   127	
   128	    const nowMs = Date.parse(this.clock.now());
   129	    const state = this.getOrCreate(tenantId, nowMs);
   130	
   131	    state.hourly = advanceWindow(state.hourly, nowMs, HOUR_MS);
   132	    state.daily = advanceWindow(state.daily, nowMs, DAY_MS);
   133	
   134	    const hourlyCheck = checkBucket(
   135	      state.hourly.spentMicros,
   136	      this.policy.hourlyTenantCeilingMicros,
   137	      price.unitsMicros,
   138	      `hourly tenant ceiling`
   139	    );
   140	    if (!hourlyCheck.ok) throw new BudgetError(hourlyCheck.reason, hourlyCheck.code);
   141	
   142	    const dailyCheck = checkBucket(
   143	      state.daily.spentMicros,
   144	      this.policy.dailyTenantCeilingMicros,
   145	      price.unitsMicros,
   146	      `daily tenant ceiling`
   147	    );
   148	    if (!dailyCheck.ok) throw new BudgetError(dailyCheck.reason, dailyCheck.code);
   149	
   150	    if (url) {
   151	      const li = matchLineItem(this.policy, url);
   152	      if (li) {
   153	        if (price.currency !== li.currency) {
   154	          throw new BudgetError(
   155	            `Line-item currency mismatch: ${li.currency} vs quote ${price.currency}`,
   156	            'LINE_ITEM_CURRENCY'
   157	          );
   158	        }
   159	        const bucket = state.lineItems[li.match] ?? { dailyMicros: 0, lifetimeMicros: 0 };
   160	        const dCheck = checkBucket(
   161	          bucket.dailyMicros,
   162	          li.dailyCeilingMicros,
   163	          price.unitsMicros,
   164	          `line-item daily (${li.match})`
   165	        );
   166	        if (!dCheck.ok) throw new BudgetError(dCheck.reason, dCheck.code);
   167	        const lCheck = checkBucket(
   168	          bucket.lifetimeMicros,
   169	          li.lifetimeCeilingMicros,
   170	          price.unitsMicros,
   171	          `line-item lifetime (${li.match})`
   172	        );
   173	        if (!lCheck.ok) throw new BudgetError(lCheck.reason, lCheck.code);
   174	      }
   175	    }
   176	  }
   177	
   178	  /**
   179	   * Record a completed paid fetch. Advances every meter that was charged
   180	   * for this call. The broker calls this exactly once per settled fetch.
   181	   */
   182	  recordPaid(tenantId: string, price: Price, url: UrlString): void {
   183	    const nowMs = Date.parse(this.clock.now());
   184	    const state = this.getOrCreate(tenantId, nowMs);
   185	    state.hourly = advanceWindow(state.hourly, nowMs, HOUR_MS);
   186	    state.daily = advanceWindow(state.daily, nowMs, DAY_MS);
   187	    state.hourly.spentMicros += price.unitsMicros;
   188	    state.daily.spentMicros += price.unitsMicros;
   189	
   190	    const li = matchLineItem(this.policy, url);
   191	    if (li) {
   192	      const bucket = state.lineItems[li.match] ?? { dailyMicros: 0, lifetimeMicros: 0 };
   193	      bucket.dailyMicros += price.unitsMicros;
   194	      bucket.lifetimeMicros += price.unitsMicros;
   195	      state.lineItems[li.match] = bucket;
   196	    }
   197	  }
   198	
   199	  /**
   200	   * Record a denied fetch. Does NOT charge, but SHOULD be observed on
   201	   * dashboards to distinguish "the agent tried and was stopped by us" from
   202	   * "the agent tried and was stopped by the origin."
   203	   *
   204	   * Denial rows live in the audit ledger; this hook is kept so a future
   205	   * in-memory rate limiter (e.g. deny-burst) can subscribe uniformly.
   206	   */
   207	  recordDenied(_tenantId: string): void {
   208	    // Intentionally no-op in-memory; the audit ledger is the source of truth.
   209	  }
   210	
   211	  /** Snapshot of current meter state for the dashboard. */
   212	  snapshot(tenantId: string): MeterState {
   213	    const state = this.meters.get(tenantId);
   214	    if (!state) throw new BudgetError(`Unknown tenant: ${tenantId}`, 'UNKNOWN_TENANT');
   215	    return structuredClone(state);
   216	  }
   217	
   218	  private getOrCreate(tenantId: string, nowMs: number): MeterState {
   219	    let state = this.meters.get(tenantId);
   220	    if (!state) {
   221	      state = emptyMeter(tenantId, { now: () => new Date(nowMs).toISOString() });
   222	      this.meters.set(tenantId, state);
   223	    }
   224	    return state;
   225	  }
   226	}
   227	
   228	// Re-export so imports don't need to reach into the policy module.
   229	export { defaultPolicy, matchLineItem, globMatch } from './policy.js';
   230	export type { BudgetPolicy, LineItem } from './policy.js';"}

{"path": "packages/rails/src/rails.ts", "start_line": 1, "end_line": 220, "total_lines": 220, "content": "     1	import {
     2	  RailError,
     3	  makeSettlementRef,
     4	  type Clock,
     5	  type PaymentRail,
     6	  type PaymentRequest,
     7	  type Quote,
     8	  type RailAuthorization,
     9	  type RailSettlement,
    10	  type Micros,
    11	} from '@mwb/core';
    12	
    13	/**
    14	 * A rail is a backend: quote → authorize → settle, all behind one
    15	 * interface. Field names inside `payload` are intentionally opaque — the
    16	 * specs churn (x402 v2, Cloudflare Pay Per Crawl are still being
    17	 * finalized), so the broker never parses them. Draft-caveat discipline:
    18	 * build against the interface, not a draft's field names.
    19	 */
    20	export interface RailBackend extends PaymentRail {}
    21	
    22	/**
    23	 * In-memory rail for tests, demos, and local dev. Mirrors the x402 shape
    24	 * (micro-unit price, `X-PAYMENT` header) without an external service.
    25	 * Deterministic: with a `frozenClock` and fixed input, the settlement
    26	 * reference is stable so reconciliation can be asserted.
    27	 */
    28	export class InMemoryRail implements PaymentRail {
    29	  readonly id: string;
    30	  private readonly settlementSeed: string = '';
    31	  private readonly failureMode: 'none' | 'quote' | 'authorize' | 'settle';
    32	
    33	  constructor(options: {
    34	    id: string;
    35	    priceMicros: Micros;
    36	    currency?: string;
    37	    clock?: Clock;
    38	    failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
    39	    /** Stable suffix seed so settlement refs are deterministic in tests. */
    40	    settlementSeed?: string;
    41	  }) {
    42	    this.id = options.id;
    43	    this.priceMicros = options.priceMicros;
    44	    this.currency = options.currency ?? 'USD';
    45	    this.clock = options.clock ?? { now: () => new Date().toISOString() };
    46	    this.failureMode = options.failureMode ?? 'none';
    47	    this.settlementSeed = options.settlementSeed ?? `${options.id}-seed`;
    48	  }
    49	
    50	  quote(_req: PaymentRequest): Promise<Quote> {
    51	    if (this.failureMode === 'quote') {
    52	      return Promise.reject(
    53	        new RailError(`${this.id}: quote failed`, 'RAIL_QUOTE', undefined, true)
    54	      );
    55	    }
    56	    const nowMs = Date.parse(this.clock.now());
    57	    return Promise.resolve({
    58	      unitsMicros: this.priceMicros,
    59	      currency: this.currency,
    60	      rail: this.id,
    61	      settlement: 'immediate',
    62	      expiresAt: new Date(nowMs + 60_000).toISOString(),
    63	    });
    64	  }
    65	
    66	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    67	    if (this.failureMode === 'authorize') {
    68	      return Promise.reject(
    69	        new RailError(`${this.id}: authorize failed`, 'RAIL_AUTHORIZE', undefined, true)
    70	      );
    71	    }
    72	    const payload = JSON.stringify({
    73	      schema: 'urn:rail:' + this.id,
    74	      amountMicros: quote.unitsMicros,
    75	      currency: quote.currency,
    76	      url: String(req.url),
    77	      method: req.method,
    78	    });
    79	    return Promise.resolve({
    80	      scheme: this.id,
    81	      payload,
    82	      settlementHeaders: { [`${this.id.replace(/[^a-z0-9]/gi, '-').toLowerCase()}-payment`]: 'authorized' },
    83	    });
    84	  }
    85	
    86	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    87	    if (this.failureMode === 'settle') {
    88	      return Promise.reject(
    89	        new RailError(`${this.id}: settle failed`, 'RAIL_SETTLE', undefined, true)
    90	      );
    91	    }
    92	    const parsed = JSON.parse(authorization.payload) as { amountMicros: number; currency: string };
    93	    return Promise.resolve({
    94	      rail: this.id,
    95	      // Deterministic from (seed, url) so tests can assert reconciliation.
    96	      settlementRef: makeSettlementRef(this.id, deterministicRand(this.settlementSeed + String(req.url))),
    97	      amountMicros: parsed.amountMicros,
    98	      currency: parsed.currency,
    99	      settledAt: this.clock.now(),
   100	    });
   101	  }
   102	}
   103	
   104	/** Self-hosted 402 rail: same interface, different origin. */
   105	export class SelfHosted402Rail extends InMemoryRail {
   106	  constructor(options: { priceMicros: Micros; clock?: Clock; tenantId?: string }) {
   107	    super({
   108	      id: 'self402',
   109	      priceMicros: options.priceMicros,
   110	      clock: options.clock,
   111	      settlementSeed: `self402-${options.tenantId ?? 'tenant'}`,
   112	    });
   113	    this._tenantId = options.tenantId;
   114	  }
   115	  private _tenantId?: string;
   116	  tenantId(): string | undefined {
   117	    return this._tenantId;
   118	  }
   119	}
   120	
   121	/**
   122	 * Wraps an existing bridge client (e.g. an ap2-x402-bridge or AP2
   123	 * rail-adapter-x402 instance) so it can be used as a rail. The broker sees
   124	 * only this minimal shape — it does not depend on the bridge's own types.
   125	 * That is the "one contract" boundary in practice.
   126	 */
   127	export interface BridgeClientShape {
   128	  quote(input: { url: string; method: string; headers: Record<string, string> }): Promise<Quote>;
   129	  authorize(input: {
   130	    url: string;
   131	    method: string;
   132	    headers: Record<string, string>;
   133	    quote: { unitsMicros: number; currency: string };
   134	  }): Promise<RailAuthorization>;
   135	  settle(input: {
   136	    url: string;
   137	    method: string;
   138	    headers: Record<string, string>;
   139	    authorization: RailAuthorization;
   140	  }): Promise<RailSettlement>;
   141	}
   142	
   143	export class BridgeRail implements PaymentRail {
   144	  constructor(
   145	    private readonly idAndBridge: { id: string; bridge: BridgeClientShape }
   146	  ) {}
   147	
   148	  get id(): string {
   149	    return this.idAndBridge.id;
   150	  }
   151	
   152	  quote(req: PaymentRequest): Promise<Quote> {
   153	    return this.idAndBridge.bridge.quote({ url: String(req.url), method: req.method, headers: req.headers });
   154	  }
   155	
   156	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
   157	    return this.idAndBridge.bridge.authorize({
   158	      url: String(req.url),
   159	      method: req.method,
