{"path": "packages/core/src/errors.ts", "start_line": 1, "end_line": 66, "total_lines": 66, "content": "     1	/**
     2	 * Base error hierarchy for the broker.
     3	 * Every error carries a stable `code` so the audit layer and agents can act
     4	 * on failures without parsing messages.
     5	 */
     6	export class BrokerError extends Error {
     7	  public readonly code: string;
     8	  public readonly retryable: boolean;
     9	
    10	  constructor(code: string, message: string, options?: { cause?: unknown; retryable?: boolean }) {
    11	    super(message, { cause: options?.cause });
    12	    this.name = new.target.name;
    13	    this.code = code;
    14	    this.retryable = options?.retryable ?? false;
    15	  }
    16	}
    17	
    18	/** The request was denied by broker policy or the budget engine before the origin was reached. */
    19	export class BudgetError extends BrokerError {
    20	  constructor(message: string, code: string = 'BUDGET_DENIED', cause?: unknown) {
    21	    super(code, message, { cause });
    22	  }
    23	}
    24	
    25	/** A payment rail failed a quote, authorization, or settlement step. */
    26	export class RailError extends BrokerError {
    27	  constructor(message: string, code: string = 'RAIL_ERROR', cause?: unknown, retryable?: boolean) {
    28	    super(code, message, { cause, retryable });
    29	  }
    30	}
    31	
    32	/** Identity/attestation failure: missing, expired, or mismatched key. */
    33	export class IdentityError extends BrokerError {
    34	  constructor(message: string, code: string = 'IDENTITY_ERROR', cause?: unknown) {
    35	    super(code, message, { cause });
    36	  }
    37	}
    38	
    39	/** License parsing or enforcement failure. */
    40	export class LicenseError extends BrokerError {
    41	  constructor(message: string, code: string = 'LICENSE_ERROR', cause?: unknown) {
    42	    super(code, message, { cause });
    43	  }
    44	}
    45	
    46	/** The origin rejected the request outright (403 bot gate, WAF, agent detection). */
    47	export class OriginRejectedError extends BrokerError {
    48	  constructor(message: string, origin: string, httpStatus: number, cause?: unknown) {
    49	    super(
    50	      `ORIGIN_REJECTED`,
    51	      `Origin ${origin} rejected the request with HTTP ${httpStatus}: ${message}`,
    52	      { cause, retryable: true }
    53	    );
    54	  }
    55	}
    56	
    57	/** The origin demanded payment (402) and no rail could or should settle it. */
    58	export class PaymentRequiredError extends BrokerError {
    59	  constructor(message: string, code: string = 'PAYMENT_REQUIRED', cause?: unknown) {
    60	    super(code, message, { cause, retryable: true });
    61	  }
    62	}
    63	
    64	export function isBrokerError(err: unknown): err is BrokerError {
    65	  return err instanceof BrokerError;
    66	}"}

{"path": "packages/core/src/time.ts", "start_line": 1, "end_line": 26, "total_lines": 26, "content": "     1	/** Injectable clock + id for deterministic tests and audit replay. */
     2	export interface Clock {
     3	  now(): string;
     4	}
     5	
     6	export const systemClock: Clock = {
     7	  now(): string {
     8	    return new Date().toISOString();
     9	  },
    10	};
    11	
    12	export const frozenClock = (t = '2026-08-18T00:00:00.000Z'): Clock => ({ now: () => t });
    13	
    14	/** Random fetch ids (rfc9562-style ULID would be a drop-in upgrade). */
    15	export function makeFetchId(rand: () => number = Math.random): string {
    16	  const alphabet = '0123456789';
    17	  let id = '';
    18	  for (let i = 0; i < 16; i++) id += alphabet[Math.floor(rand() * 16)]!;
    19	  return `fetch_${id}`;
    20	}
    21	
    22	export function makeSettlementRef(rail: string, rand: () => number = Math.random): string {
    23	  let suffix = '';
    24	  for (let i = 0; i < 12; i++) suffix += 'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(rand() * 36)]!;
    25	  return `settle_${rail}_${suffix}`;
    26	}"}

