{"path": "packages/budget/src/policy.ts", "start_line": 1, "end_line": 97, "total_lines": 97, "content": "     1	import type { FailureClass, Price, UrlString } from '@mwb/core';
     2	
     3	/**
     4	 * Budget decision returned by the BudgetEngine before the broker does any
     5	 * network work, or after it observes the origin's response.
     6	 *
     7	 * The point: a "generic failure" is no longer reportable. Every terminal
     8	 * state maps to one of the three classes so an agent (or a human dashboard)
     9	 * can say exactly why the cost decision happened.
    10	 */
    11	export type PreFlightDecision =
    12	  | {
    13	      kind: 'allow';
    14	      /** The price quote the engine will pay without further action. */
    15	      quote: Price;
    16	      /** Rail the quote came from; the broker pays through this rail. */
    17	      rail: string;
    18	      note?: string;
    19	    }
    20	  | {
    21	      kind: 'require-settlement';
    22	      /** Quote that needs an explicit settlement authorization. */
    23	      quote: Price;
    24	      rail: string;
    25	      reason: string;
    26	    }
    27	  | {
    28	      kind: 'deny';
    29	      failureClass: Extract<FailureClass, 'blocked' | 'token-rejected'>;
    30	      code: string;
    31	      reason: string;
    32	    };
    33	
    34	export type OutcomeDecision =
    35	  | { kind: 'record-paid'; failureClass?: never }
    36	  | { kind: 'record-denied'; failureClass: FailureClass; code?: string; reason: string };
    37	
    38	/**
    39	 * A line-item: the recurring ceiling that groups URLs (e.g. all fetches to
    40	 * news-site.com, or a domain group). Treated like a monthly credit line.
    41	 */
    42	export interface LineItem {
    43	  /** Glob over host + path. Supports `*` anywhere. */
    44	  match: string;
    45	  /** Max spend per calendar day, in micros. */
    46	  dailyCeilingMicros: number;
    47	  /** Hard cap over the line item's lifetime, in micros. */
    48	  lifetimeCeilingMicros: number;
    49	  currency: string;
    50	  label?: string;
    51	}
    52	
    53	/**
    54	 * Tenant-level policy. All ceilings are in micros (1/1,000,000 of a unit).
    55	 * Defaults are chosen to be strict enough to be useful and loose enough
    56	 * not to block a demo: one fetch must always fit inside every ceiling.
    57	 */
    58	export interface BudgetPolicy {
    59	  /** Absolute cap per fetch, in micros. Default 10_000 (0.01). */
    60	  perCallCeilingMicros: number;
    61	  /** Cap per tenant per rolling hour, in micros. Default 100_000 (0.10). */
    62	  hourlyTenantCeilingMicros: number;
    63	  /** Cap per tenant per rolling day, in micros. Default 1_000_000 (1.00). */
    64	  dailyTenantCeilingMicros: number;
    65	  currency: string;
    66	  /** Line items are consulted after the per-call check; a fetch can fit
    67	   * the per-call rule but still exceed the line-item rule. */
    68	  lineItems: LineItem[];
    69	}
    70	
    71	export const defaultPolicy: BudgetPolicy = Object.freeze({
    72	  perCallCeilingMicros: 10_000,
    73	  hourlyTenantCeilingMicros: 100_000,
    74	  dailyTenantCeilingMicros: 1_000_000,
    75	  currency: 'USD',
    76	  lineItems: [],
    77	});
    78	
    79	export function matchLineItem(policy: BudgetPolicy, url: UrlString): LineItem | undefined {
    80	  const u = new URL(url);
    81	  const haystack = u.host + u.pathname;
    82	  return policy.lineItems.find((li) => globMatch(li.match, haystack) ?? false);
    83	}
    84	
    85	/** A very small glob: `*` matches any run of chars. Sufficient for the
    86	 *  line-item matcher; not a general-purpose path matcher on purpose. */
    87	export function globMatch(pattern: string, haystack: string): boolean {
    88	  const re = new RegExp(
    89	    '^' +
    90	      pattern
    91	        .split('*')
    92	        .map((part) => part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
    93	        .join('.*') +
    94	      '$'
    95	  );
    96	  return re.test(haystack);
    97	}"}

