     2	import type { LedgerEntry } from '@mwb/core';
     3	import { summarize } from './ledger.js';
     4	
     5	/**
     6	 * A minimal, dependency-free text dashboard. Deliberately dumb: pipe its
     7	 * output anywhere — CI logs, a status page, an ops channel — and the three
     8	 * failure classes stay visible. The moat is *seeing* these rows, which is
     9	 * what collapses into a generic failure today.
    10	 */
    11	export function renderDashboard(rows: LedgerEntry[], title = 'Metered Web Broker'): string {
    12	  const s = summarize(rows);
    13	  const bar = '─'.repeat(70);
    14	  const lines: string[] = [];
    15	  lines.push(`┌${bar}┐`);
    16	  lines.push(`│ ${title.padEnd(70)} │`);
    17	  lines.push(`└${bar}┘`);
    18	  lines.push(`  total ${s.total}   fulfilled ${s.fulfilled}   denied ${s.denied}`);
    19	  const classes = Object.entries(s.byFailureClass)
    20	    .sort(([a], [b]) => (a < b ? -1 : 1))
    21	    .map(([k, v]) => `${k}=${v}`)
    22	    .join('  ');
    23	  if (classes) lines.push(`  classes  ${classes}`);
    24	  if (s.spendMicros > 0) lines.push(`  spend    ${formatMicros(s.spendMicros)}`);
    25	  lines.push('');
    26	
    27	  const cols: Array<[string, (r: LedgerEntry) => string]> = [
    28	    ['seq', (r) => String(r.seq)],
    29	    ['fetch_id', (r) => r.fetchId],
    30	    ['status', (r) => r.status],
    31	    ['class', (r) => r.failureClass ?? '-'],
    32	    ['http', (r) => (r.httpStatus != null ? String(r.httpStatus) : '-')],
    33	    ['price', (r) => (r.priceMicros != null ? formatMicros(r.priceMicros) : '-')],
    34	    ['rail', (r) => r.rail ?? '-'],
    35	  ];
    36	  const widths = cols.map(([label, get]) =>
    37	    Math.max(label.length, ...rows.map((r) => get(r).length))
    38	  );
    39	  const pad = (i: number, t: string) => t.padEnd(widths[i] ?? 0);
    40	  lines.push(cols.map(([label], i) => pad(i, label.toUpperCase())).join('   '));
    41	  lines.push('-'.join(widths.map((w) => '-'.repeat(w))).replace(/\s+/g, ''));
    42	  for (const r of rows) lines.push(cols.map(([_l, get], i) => pad(i, get(r))).join('   '));
    43	
    44	  return lines.join('\n');
