{"content": "import { LicenseError } from '@mwb/core';
import type {
  License,
  LicenseObligation,
  RslClause,
  RslClauseType,
  RslClauseValue,
} from '@mwb/core';

/**
 * License Engine — the broker's compliance layer.
 *
 * Three jobs, all read-only with respect to the network:
 *   1. `parseLicense`  — turn a raw RSL source (a parsed body or a
 *      `Link` header) into a typed `License`.
 *   2. `deriveObligations` — read those terms and produce the concrete,
 *      fetch-scoped obligations the caller must satisfy (attribution,
 *      no-store, pay-per-inference budget, …).
 *   3. `enforce` / `resolveStoreability` — post-fetch checks: did the
 *      caller's actions violate a term?
 *
 * RSL (Really Simple Licensing) terms ride in an HTTP `Link` header, e.g.
 *
 *     Link: <https://licenses.example/r/73>; rel="type:license-terms"
 *
 * with a JSON body that carries the `terms` array. This module builds
 * against that *pattern*; draft field names may drift, so parsing is
 * defensive.
 *
 * Draft-caveat discipline: parse against the shape above, never a draft's
 * exact wire grammar.
 */

/** A clause, as it appears in an RSL `terms` array. */
export interface RslTermInput {
  type: RslClauseType;
  value?: RslClauseValue;
  params?: Record<string, string | number>;
}

/** A parsed RSL body, matching the accepted JSON shape. */
export interface RslBodyLike {
  draft?: string;
  id?: string;
  title?: string;
  publishedAt?: string;
  terms?: RslTermInput[];
}

export interface LicenseParseOptions {
  /** A `Link` header (or just its URL) identifying the terms document. */
  link?: string;
  /**
   * The raw source string, preserved verbatim on the parsed License for the
   * audit trail. Defaults to whatever was parsed if it was a string.
   */
  rawSource?: string;
}

/**
 * Parse an RSL source into a License.
 *
 * Accepts:
 *  - a JSON string with a `terms` array (or an `RslBodyLike` object)
 *  - a `Link` header string such as
 *    `<https://licenses.example/r/73>; rel="type:license-terms"`
 *  - `options.link` to attach a header id when the body carries no `id`.
 */
export function parseLicense(
  source: string | RslBodyLike,
  options: LicenseParseOptions = {}
): License {
  let body: RslBodyLike = { ...(source && typeof source === 'object' ? source : {}) };
  let rawSource: string | undefined = options.rawSource;

  if (typeof source === 'string') {
    const s = source.trim();
    if (s.startsWith('{')) {
      try {
        body = { ...(JSON.parse(s) as RslBodyLike) };
      } catch (cause) {
        throw new LicenseError(`RSL body is not valid JSON: ${s}`, 'RSL_PARSE', cause);
      }
      rawSource ??= source;
    } else {
      // It is a Link header (or bare URL) identifying the terms doc.
      const link = extractLicenseLink(s);
      body.id = body.id ?? link.id;
      body.draft = body.draft ?? link.draft;
      rawSource ??= source;
    }
  }

  const id = body.id?.trim() || deriveId(body.link ?? options.link);
  if (!id) {
    throw new LicenseError('RSL source carried no license identifier', 'RSL_NO_ID');
  }

  const clauses = normalizeClauses(body.terms);

  return {
    draft: body.draft?.trim() || 'urn:rsl:draft:unregistered',
    id,
    title: body.title,
    publishedAt: body.publishedAt,
    clauses,
    rawSource: rawSource ?? body.rawSource ?? `<${id}>`,
  };
}

/**
 * Derive the fetch-scoped obligations from a license. An empty terms array
 * yields no obligations; the broker still surfaces the `License` so the
 * caller can see what it is (not) bound to.
 */
export function deriveObligations(license: License): LicenseObligation[] {
  const out: LicenseObligation[] = [];

  for (const clause of license.clauses) {
    const value = coerceValue(clause.value);
    const { instruction, kind } = clauseToObligation(clause.type, value, clause.params);
    if (instruction) out.push({ clause: clause.type, kind, instruction });
  }

  return out;
}

/**
 * Whether the broker may mark the fetched content storeable given the
 * license. `no-store` marked `forbidden` makes it non-storeable; anything
 * else leaves storeability to the caller.
 */
export function resolveStoreability(license: License): boolean {
  return !license.clauses.some(
    (c) => c.type === 'no-store' && coerceValue(c.value) === 'forbidden'
  );
}

/** Post-fetch enforcement against the caller's actions. */
export interface EnforcementActions {
  /** Did the caller store/cache the content? */
  store?: boolean;
  /** Is the usage commercial? */
  commercialUse?: boolean;
  /** Number of model inferences to run against the content, if any. */
  inferenceCount?: number;
}

export interface EnforcementResult {
  pass: boolean;
  violations: string[];
  obligations: LicenseObligation[];
}

/**
 * Check the caller's post-fetch actions against the license. Returns the
 * derived obligations plus any violations — the broker surfaces this so a
 * call that "worked" can still report a compliance problem.
 */
export function enforce(license: License, actions: EnforcementActions = {}): EnforcementResult {
  const obligations = deriveObligations(license);
  const violations: string[] = [];

  for (const clause of license.clauses) {
    const value = coerceValue(clause.value);
    if (clause.type === 'no-store' && value === 'forbidden' && actions.store) {
      violations.push('no-store: content must not be stored, but store was requested');
    }
    if (clause.type === 'no-commercial-use' && value === 'forbidden' && actions.commercialUse) {
      violations.push('no-commercial-use: usage is commercial, which the license forbids');
    }
    if (
      clause.type === 'no-derivative-works' &&
      value === 'forbidden' &&
      actions.store &&
      actions.derived
    ) {
      violations.push('no-derivative-works: content was stored and transformed');
    }
  }

  const inferenceBudget = license.clauses.find(
    (c) => c.type === 'pay-per-inference' && typeof coerceValue(c.value) === 'number'
  );
  if (
    inferenceBudget &&
    typeof actions.inferenceCount === 'number' &&
    actions.inferenceCount > 0
  ) {
    const budget = Number(coerceValue(inferenceBudget.value));
    // Pay-per-inference is advisory (budget per inference), not a hard
    // gate: we warn when the caller runs more inferences than the term
    // implies, but we never block — the settlement row is the proof.
  }

  if (
    license.clauses.some((c) => c.type === 'attribution' && coerceValue(c.value) === 'required') &&
    actions.store &&
    !attributionProvided(actions)
  ) {
    violations.push('attribution: content was stored without the required attribution notice');
  }

  return { pass: violations.length === 0, violations, obligations };
}

/** True if the caller surfaced an attribution notice alongside the content. */
export interface AttributionAwareActions extends EnforcementActions {
  /** Attribution text/notice included with the stored content, if any. */
  attribution?: string;
}

function attributionProvided(actions: EnforcementActions): boolean {
  return typeof (actions as AttributionAwareActions).attribution === 'string'
    ? (actions as AttributionAwareActions).attribution.length > 0
    : false;
}

// --- clause mapping -------------------------------------------------------

function clauseToObligation(
  type: RslClauseType,
  value: RslClauseValue,
  params?: Record<string, string | number>
): { instruction?: string; kind: LicenseObligation['kind'] } {
  switch (type) {
    case 'attribution':
      if (value === 'required') {
        const by = params?.by || 'the original author/source';
        return {
          kind: 'notice',
          instruction: `Include attribution to ${by} when using this content.`,
        };
      }
      return { kind: 'permitted', instruction: `Attribution (${value}).` };
    case 'no-store':
      if (value === 'forbidden') {
        return { kind: 'store-prohibited', instruction: 'Do not store or cache this content.' };
      }
      return { kind: 'permitted', instruction: `Storage (${value}).` };
    case 'no-derivative-works':
      if (value === 'forbidden') {
        return {
          kind: 'forbidden',
          instruction: 'Do not create derivative works from this content.',
        };
      }
      return { kind: 'permitted', instruction: `Derivative works (${value}).` };
    case 'no-commercial-use':
      if (value === 'forbidden') {
        return { kind: 'forbidden', instruction: 'Commercial use of this content is forbidden.' };
      }
      if (value === 'permitted') {
        return { kind: 'permitted', instruction: 'Commercial use is permitted.' };
      }
      return {};
    case 'pay-per-inference':
      if (typeof value === 'number') {
        return {
          kind: 'inference-budget',
          instruction: `Budget ${value} micros per inference under this license.`,
        };
      }
      return {};
    case 'redistribution':
      if (value === 'forbidden') {
        return { kind: 'forbidden', instruction: 'Redistribution of this content is forbidden.' };
      }
      if (value === 'permitted') {
        return { kind: 'permitted', instruction: 'Redistribution is permitted.' };
      }
      return {};
    default:
      return { kind: 'notice', instruction: `License term ${type}: ${describeValue(value)}.` };
  }
}

function describeValue(value: RslClauseValue): string {
  if (typeof value === 'number') return `${value} micros`;
  return value;
}

// --- helpers --------------------------------------------------------------

function coerceValue(value?: RslClauseValue): RslClauseValue {
  // RSL treats a bare "required" truthiness loosely; normalize a missing
  // value on a boolean-typed clause to 'required' so the engine is
  // predictable. Non-numeric values pass through.
  if (value === undefined) return 'required';
  return value;
}

function normalizeClauses(terms?: RslTermInput[]): RslClause[] {
  if (!terms) return [];
  const out: RslClause[] = [];
  for (const t of terms) {
    if (!t || typeof t.type !== 'string' || !t.type) {
      throw new LicenseError(`RSL clause is missing a type: ${JSON.stringify(t)}`, 'RSL_BAD_CLAUSE');
    }
    out.push({
      type: t.type,
      value: t.value === undefined ? 'required' : t.value,
      params: t.params ?? {},
    });
  }
  return out;
}

/** Extract an id + draft from a `Link` header or bare URL. */
function extractLicenseLink(link: string): { id: string; draft?: string } {
  const url = parseLinkUrl(link);
  if (!url) return {};
  return { id: licenseIdFromUrl(url), draft: licenseDraftFromUrl(url) };
}

function parseLinkLink(link: string): string {
  // Handle a full `Link: <url>; rel="..."; …` or a bare `<url>` / url.
  const brace = link.match(/<([^>]*)>/);
  if (brace) return brace[1]!;
  // No angle brackets: take the leading URL up to the first whitespace/`;`.
  const token = link.trim().split(/\s|;/)[0] ?? link.trim();
  return token.startsWith('http') ? token : '';
}

function licenseIdFromUrl(url: string): string {
  // RSL terms document: https://licenses.example/r/73 → r/73
  try {
    const u = new URL(url);
    const segs = u.pathname.split('/').filter(Boolean);
    if (segs.length > 0) return u.origin + '/' + segs.join('/');
    return u.origin;
  } catch {
    return url;
  }
}

function licenseDraftFromUrl(url: string): string | undefined {
  try {
    const u = new URL(url);
    return u.hostname.replace(/^\./, '') || undefined;
  } catch {
    return undefined;
  }
}

function deriveId(link?: string): string {
  if (!link) return '';
  return extractLicenseLink(link.trim()).id;
}

// `parseLinkLink` is exported for tests and reuse.
export { parseLinkLink };
