  const wantsAttribution = license.clauses.some((c) => c.type === 'attribution' && c.value === 'required');
  if (wantsAttribution && actions.store && !attributionProvided(actions)) {
    violations.push('attribution: content was stored without the required attribution notice');
  }

  return { pass: violations.length === 0, violations, obligations: deriveObligations(license) };
}

function attributionProvided(actions: EnforcementActions): boolean {
  return typeof actions.attribution === 'string' && actions.attribution.length > 0;
}

// --- clause mapping -------------------------------------------------------

/** Translate a single clause to the obligation it imposes, if any. */
function clauseToObligation(
  type: string,
  params?: Record<string, string | number>
): { instruction?: string; kind: LicenseObligation['kind'] } {
  switch (type) {
    case 'attribution':
      if (params?.by) return { kind: 'notice', instruction: `Include attribution to ${params.by} when using this content.` };
      return { kind: 'notice', instruction: 'Include attribution when using this content.' };
    case 'no-store':
      return { kind: 'store-prohibited', instruction: 'Do not store or cache this content.' };
    case 'no-derivative-works':
      return { kind: 'forbidden', instruction: 'Do not create derivative works from this content.' };
    case 'no-commercial-use':
      return { kind: 'forbidden', instruction: 'Commercial use of this content is forbidden.' };
    case 'redistribution':
      return { kind: 'forbidden', instruction: 'Redistribution of this content is forbidden.' };
    default:
      return { kind: 'notice', instruction: `License term ${type} applies; review its conditions.` };
  }
}

// --- helpers --------------------------------------------------------------

/** RSL treats a bare clause as required; the engine is predictable about it. */
function normalizeClauses(terms?: RslTermInput[]): RslClause[] {
  if (!terms) return [];
  const out: RslClause[] = [];
  for (const t of terms) {
    if (!t || typeof t.type !== 'string' || !t.type) {
      throw new LicenseError(`RSL clause is missing a type: ${JSON.stringify(t)}`, 'RSL_BAD_CLAUSE');
    }
    out.push({
      type: t.type,
      value: t.value ?? 'required',
      params: t.params ?? {},
    });
  }
  return out;
}

/** Parse a `Link` header (or bare URL) into { id, draft }. */
function extractLink(link: string): { id: string; draft?: string } {
  const url = linkUrl(link);
  if (!url) return { id: '' };
  return { id: slugFromUrl(url), draft: draftFromUrl(url) };
}

/** A `Link: <url>; rel="..."` or a bare `<url>` / url → the URL string. */
function linkUrl(link: string): string {
  const brace = link.match(/<([^>]*)>/);
  if (brace) return brace[1]!;
  const token = (link.trim().split(/\s|;/)[0] ?? '').trim();
  return token.startsWith('http') ? token : '';
}

/** https://h.example.com/r/73 → https://h.example.com/r/73. */
function slugFromUrl(url: string): string {
  try {
    return new URL(url).href;
  } catch {
    return url;
  }
}

/** A draft label is best-effort; used only if the body carried no draft. */
function draftFromUrl(url: string): string | undefined {
  try {
    return new URL(url).hostname || undefined;
  } catch {
    return undefined;
  }
}

/** Alias used by the top-level parse path for a link given via options. */
function linkId(link?: string): string {
  if (!link) return '';
  return extractLink(link.trim()).id;
}
