{"content": "import {
  BudgetError,
  HeaderRecord,
  IdentityError,
  PaymentRequiredError,
  RailError,
  isBrokerError,
  makeFetchId,
  systemClock,
  type Clock,
  type FetchOutcome,
  type FailureClass,
  type Price,
  type PaymentRail,
  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type UrlString,
} from '@mwb/core';
import { BudgetEngine } from '@mwb/budget';
import { AuditLedger } from '@mwb/audit';
import { KeyRing } from '@mwb/identity';
import {
  deriveObligations,
  enforce,
  parseLicense,
  resolveStoreability,
  type RslBodyLike,
} from '@mwb/license';

/**
 * The Metered Web Broker orchestrator.
 *
 * `Broker.fetch` is the single "one contract" call: it composes the budget
 * gate, the payment rail, best-effort identity, the license engine, and the
 * audit ledger into one outcome. Everything below is designed around a
 * single invariant:
 *
 *   every terminal path is one of {fulfilled, blocked, payment-required,
 *   token-rejected} — `error` status is deliberately NOT produced, because a
 *   generic failure would hide the cost decision.
 *
 * Flow (budget gate is the first deny-gate):
 *
 *   1. rail.quote(request)               -> quote (the origin's price)
 *   2. budget.preflight(quote)           -> `blocked` if the policy denies it
 *   3. rail.authorize(request, quote)    -> RailError  -> `payment-required`
 *   4. rail.settle(request, auth)        -> RailError  -> `payment-required`
 *   5. identity.bestEffortSign(request)  -> recorded, never a gate
 *   6. origin.fetch(request + settlement)-> content   -> `fulfilled`
 *                                        -> 402         -> `payment-required`
 *                                        -> 403 (id)    -> `token-rejected`
 *                                        -> 403 (no id) -> `blocked`
 *                                        -> other       -> `blocked`
 *   7. license.parse + derive from origin Link header (if present)
 *
 * On `fulfilled` only: `BudgetEngine.recordPaid` is called exactly once, and
 * exactly one `AuditLedger` row is recorded for the `fetchId`.
 */

/** What the origin returns: a status, headers (where RSL rides), body. */
export interface OriginResponse {
  httpStatus: number;
  headers: HeaderRecord;
  body: string;
}

/**
 * The content/SLA source. The rail is the *payment* facilitator; the origin
 * is what is metered. Keeping them separate is the one-contract boundary:
 * the broker pays through the rail and reads content/license from the origin.
 */
export interface OriginClient {
  fetch(req: PaymentRequest): Promise<OriginResponse>;
}

export interface BrokerIdentityOptions {
  /** Subject/tenant to embed in the PACT attestation, if a ring is present. */
  subject?: string;
  /**
   * If true, a presented identity is mandatory for fulfillment. Default false
   * (Phase 1: identity is best-effort and recorded, not a hard gate).
   */
  required?: boolean;
}

export interface BrokerOptions {
  rail: PaymentRail;
  budget: BudgetEngine;
  ledger: AuditLedger;
  /** Identity vault. Absent ⇒ no identity presented (a 403 from origin then reads as `blocked`). */
  ring?: KeyRing;
  /** Content/SLA source. Absent ⇒ a successful rail settle is treated as fulfillment. */
  origin?: OriginClient;
  clock?: Clock;
  identity?: BrokerIdentityOptions;
  /**
   * Extra headers presented on every origin fetch (e.g. user-agent). Merged
   * with settlement headers. Never secrets.
   */
  headers?: HeaderRecord;
}

/** A non-fatal identity problem, surfaced (not thrown) on the outcome. */
export interface IdentityWarning {
  code: string;
  message: string;
}

const TERMINAL = ['fulfilled', 'denied'] as const;

/**
 * The Broker. One call composes the whole metered-web decision stack.
 *
 * Injecting every collaborator (rail, budget, ledger, ring, origin, clock)
 * is what makes the terminal-path mapping and the "record exactly one row /
 * recordPaid once" guarantee fully testable.
 */
export class Broker {
  private readonly rail: PaymentRail;
  private readonly budget: BudgetEngine;
  private readonly ledger: AuditLedger;
  private readonly ring?: KeyRing;
  private readonly origin?: OriginClient;
  private readonly clock: Clock;
  private readonly identityOpts: BrokerIdentityOptions;
  private readonly headers: HeaderRecord;

  /** Cache of resolved outcomes, keyed by fetchId — guarantees one row + one charge per id. */
  private readonly outcomes = new Map<string, FetchOutcome>();

  constructor(options: BrokerOptions) {
    this.rail = options.rail;
    this.budget = options.budget;
    this.ledger = options.ledger;
    this.ring = options.ring;
    this.origin = options.origin;
    this.clock = options.clock ?? systemClock;
    this.identityOpts = options.identity ?? {};
    this.headers = options.headers ?? {};
  }

  /**
   * Perform one metered fetch and return its terminal outcome.
   *
   * Idempotent by `fetchId`: a second call with the same id returns the
   * cached outcome without re-quoting, re-settling, or charging the meter.
   */
  async fetch(params: {
    url: UrlString;
    fetchId?: string;
    headers?: HeaderRecord;
    tenantId?: string;
    rand?: () => number;
  }): Promise<FetchOutcome> {
    const fetchId = params.fetchId ?? makeFetchId(params.rand);
    const existing = this.outcomes.get(fetchId);
    if (existing) return this.cloneOutcome(existing);

    const startedAt = this.clock.now();
    const tenantId = params.tenantId ?? 'default';

    try {
      const outcome = await this.run(params.url, fetchId, tenantId, params.headers);
      outcome.timestamps.completedAt = this.clock.now();
      // The ledger row already carries the terminal truth; cache the outcome
      // so a duplicate fetchId cannot create a second row or a second charge.
      this.outcomes.set(fetchId, outcome);
      return outcome;
    } catch (err) {
      // Internal/unexpected errors surface rather than masquerade as a
      // denial class — there is no denied terminal for a genuine fault.
      outcomeCompleted(err); // keep the shape honest for readers
      throw err;
    } finally {
      void startedAt;
    }
  }

  /** The single resolved outcome for a fetchId, or undefined. */
  outcomeFor(fetchId: string): FetchOutcome | undefined {
    const o = this.outcomes.get(fetchId);
    return o ? this.cloneOutcome(o) : undefined;
  }

  /** One row per fetchId is guaranteed by `AuditLedger.record` being idempotent. */
  rowFor(fetchId: string) {
    return this.ledger.entries.find((e) => e.fetchId === fetchId);
  }

  // --- the compose pipeline ---------------------------------------------

  private async run(
    url: UrlString,
    fetchId: string,
    tenantId: string,
    extraHeaders?: HeaderRecord
  ): Promise<FetchOutcome> {
    const req = this.paymentRequest(url, extraHeaders);

    // 1. Quote the rail — this is the origin's price, needed to gate on budget.
    const quote = await this.rail.quote(req);

    // 2. Budget gate (the first deny-gate). A BudgetError is policy denial.
    try {
      this.budget.preflight(tenantId, quote, url);
    } catch (err) {
      if (err instanceof BudgetError || (err && isBrokerError(err) && err.code === 'CURRENCY_MISMATCH')) {
        return this.denied('blocked', err, { url, httpStatus: undefined, reason: err instanceof Error ? err.message : String(err) });
      }
      throw err;
    }

    // 3. Authorize. A rail error here means payment could not be arranged.
    const authorization: RailAuthorization = await this.rail.authorize(req, quote).catch((err) => {
      throw railDenied(err, 'authorize', this.rail.id);
    });

    // 4. Settle — the payment commit. Record the settlement ref on the outcome.
    const settlement: RailSettlement = await this.rail.settle(req, authorization).catch((err) => {
      throw railDenied(err, 'settle', this.rail.id);
    });

    // 5. Identity — best effort. Recorded on the outcome, never a hard gate.
    const { identity, identityErrors } = this.signIdentity(req);

    // 6. Fetch content from the origin, settlement headers applied.
    const originResp =
      this.origin != null
        ? await this.origin
            .fetch({ ...req, headers: { ...req.headers, ...authorization.settlementHeaders } })
            .catch((err) => {
              throw originRejected(err, !!identity);
            })
        : null;

    if (originResp != null) {
      const mapped = mapOriginResponse(originResp, !!identity, this.clock.now());
      if (mapped.status === 'denied') {
        return this.denied(
          mapped.failureClass!,
          new PaymentRequiredError(mapped.reason, mapped.code, identityErrors),
          {
            url,
            httpStatus: originResp.httpStatus,
            reason: mapped.reason,
          }
        );
      }
      // fulfilled
      return this.fulfilled({
        url,
        fetchId,
        tenantId,
        quote,
        settlement,
        identity,
        origin: originResp,
      });
    }

    // No origin client: the rail settle itself is the proof-of-payment.
    return this.fulfilled({
      url,
      fetchId,
      tenantId,
      quote,
      settlement,
      identity,
      origin: { httpStatus: 200, headers: {}, body: '' },
    });
  }

  // --- outcome builders --------------------------------------------------

  private fulfilled(args: {
    url: UrlString;
    fetchId: string;
    tenantId: string;
    quote: Quote;
    settlement: RailSettlement;
    identity?: IdentityPresentationLike;
    origin: OriginResponse;
  }): FetchOutcome {
    // 7. License, if the origin publishes RSL terms.
    const license = parseOriginLicense(args.origin.headers);
    const obligations = license ? deriveObligations(license) : [];
    const storeable = license ? resolveStoreability(license) : true;

    // Charge the tenant meter exactly once, on fulfillment.
    this.budget.recordPaid(
      args.tenantId,
      { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
      args.url
    );

    const outcome: FetchOutcome = {
      fetchId: args.fetchId,
      status: 'fulfilled',
      reason: 'content released after settlement',
      origin: { url: String(args.url), httpStatus: args.origin.httpStatus },
      content: {
        body: args.origin.body,
        contentType: args.origin.headers['content-type'] ?? 'application/octet-stream',
        storeable,
        attributionNotice: attributionNotice(license),
      },
      license,
      obligations,
      price: { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
      quote: args.quote,
      rail: args.settlement.rail,
      settlementRef: args.settlement.settlementRef,
      identity: identityToPresentation(args.identity),
      tenantId: args.tenantId,
      timestamps: { startedAt: this.clock.now(), completedAt: this.clock.now() },
    };

    this.ledger.record(outcome, { tenantId: args.tenantId });
    return outcome;
  }

  private denied(
    failureClass: FailureClass,
    err: Error & { identityWarnings?: IdentityWarning[] },
    info: { url: UrlString; httpStatus?: number; reason: string }
  ): FetchOutcome {
    const warnings = err.identityWarnings;
    const outcome: FetchOutcome = {
      fetchId: err instanceof Error && 'fetchId' in (err as object) ? (err as { fetchId?: string }).fetchId : undefined,
      status: 'denied',
      failureClass,
      reason: info.reason,
      origin: info.httpStatus != null
        ? { url: String(info.url), httpStatus: info.httpStatus }
        : { url: String(info.url) },
      error: warnings && warnings.length > 0
        ? { code: failureClass, message: info.reason, identityWarnings: warnings }
        : { code: failureClass, message: info.reason },
      timestamps: { startedAt: this.clock.now(), completedAt: this.clock.now() },
    };

    this.budget.recordDenied(info.httpStatus != null ? '' : '');
    this.ledger.record(outcome, { tenantId: outcome.tenantId });
    return outcome;
  }

  // --- helpers -----------------------------------------------------------

  private paymentRequest(url: UrlString, extraHeaders?: HeaderRecord): PaymentRequest {
    return {
      url,
      method: 'GET',
      headers: {
        host: new URL(String(url)).host,
        'user-agent': 'metered-web-broker/0.1',
        ...this.headers,
        ...(extraHeaders ?? {}),
      },
    };
  }

  /** Best-effort identity: sign the presented headers and (optionally) issue a PACT. */
  private signIdentity(req: PaymentRequest): {
    identity?: IdentityPresentationLike;
    identityErrors?: IdentityWarning[];
  } {
    const warnings: IdentityWarning[] = [];
    if (!this.ring) return { identity: undefined, identityErrors: warnings.length ? warnings : undefined };

    const keyId = this.ring.active()[0]?.keyId;
    if (!keyId) {
      warnings.push({ code: 'IDENTITY_NO_ACTIVE_KEY', message: 'no active signing key in the ring' });
      return { identity: undefined, identityErrors: warnings };
    }

    // Build the canonical block the origin can verify: host + date.
    const signingHeaders: HeaderRecord = {
      host: new URL(String(req.url)).host,
      date: this.clock.now(),
      ...req.headers,
    };

    let signatureFields: string[];
    try {
      const signed = this.ring.sign(keyId, signingHeaders, ['host', 'date']);
      signatureFields = signed.signature.split('fields="')[1]!.split('"')[0]!.split(' ');
    } catch (cause) {
      if (cause instanceof IdentityError) {
        warnings.push({ code: cause.code, message: `identity signing skipped: ${cause.message}` });
        return { identity: undefined, identityErrors: warnings };
      }
      throw cause;
    }

    let pactToken: string | undefined;
    const subject = this.identityOpts.subject ?? req.headers['x-subject'] ?? '';
    if (subject) {
      try {
        // eslint-disable-next-line @typescript-eslint/no-require-imports
        const pact = PACT_issue(this.ring, keyId, subject);
        if (pact) pactToken = pact.token;
      } catch {
        warnings.push({ code: 'PACT_ISSUE_FAILED', message: 'PACT issuance skipped (best-effort)' });
      }
    }

    return {
      identity: {
        keyId,
        algorithm: 'ed25519',
        signedHeaders: signatureFields,
        timestamp: this.clock.now(),
        pactToken,
      },
      identityErrors: warnings,
    };
  }

  // --- small private mutators for the read-side helpers ------------------

  private cloneOutcome(o: FetchOutcome): FetchOutcome {
    return { ...o, timestamps: { ...o.timestamps } } as FetchOutcome;
  }
}

/**
 * Identity presentation as carried in the outcome (identity is best-effort,
 * so `signedHeaders` reflects what was actually signed when it succeeded).
 */
interface IdentityPresentationLike {
  keyId: string;
  algorithm: 'ed25519';
  signedHeaders: string[];
  timestamp: string;
  pactToken?: string;
}

function identityToPresentation(x?: IdentityPresentationLike): FetchOutcome['identity'] {
  if (!x) return undefined;
  return {
    keyId: x.keyId,
    algorithm: x.algorithm,
    signedHeaders: x.signedHeaders,
    timestamp: x.timestamp,
    ...(x.pactToken ? { pactToken: x.pactToken } : {}),
  };
}

/**
 * Map an origin response (after settlement) to a terminal status.
 * 2xx → fulfilled; 402 → payment-required; 403 with identity → token-rejected,
 * 403 without identity → blocked; anything else → blocked.
 */
function mapOriginResponse(
  resp: OriginResponse,
  identityPresent: boolean,
  now: string
): { status: 'fulfilled' | 'denied'; failureClass?: FailureClass; reason: string; code: string } {
  const { httpStatus } = resp;
  if (httpStatus >= 200 && httpStatus < 300) {
    return { status: 'fulfilled', reason: 'origin returned content', code: 'ORIGIN_OK' };
  }
  if (httpStatus === 402) {
    return {
      status: 'denied',
      failureClass: 'payment-required',
      reason: 'origin still demanded payment after settlement (payment required, not obtainable)',
      code: 'PAYMENT_REQUIRED',
    };
  }
  if (httpStatus === 403) {
    if (identityPresent) {
      return {
        status: 'denied',
        failureClass: 'token-rejected',
        reason: 'origin rejected the presented attestation/identity (HTTP 403)',
        code: 'TOKEN_REJECTED',
      };
    }
    return {
      status: 'denied',
      failureClass: 'blocked',
      reason: 'origin blocked the request without a presented identity (HTTP 403)',
      code: 'ORIGIN_BLOCKED',
    };
  }
  return {
    status: 'denied',
    failureClass: 'blocked',
    reason: `origin rejected the request with HTTP ${httpStatus}`,
    code: 'ORIGIN_REJECTED',
  };
}

/** Build a `payment-required` fault (rail could not arrange payment). */
function railDenied(err: unknown, step: 'authorize' | 'settle', railId: string): Error & { identityWarnings?: IdentityWarning[] } {
  const base = isBrokerError(err) ? err : undefined;
  const railErr =
    base ??
    new RailError(`${railId}: ${step} failed`, 'RAIL_ERROR', err, true);
  const e = railErr as Error & { identityWarnings?: IdentityWarning[] };
  e.identityWarnings = undefined;
  return e;
}

/** Build a terminal fault from an origin client error. */
function originRejected(err: unknown, identityPresent: boolean): Error & { identityWarnings?: IdentityWarning[] } {
  const isOriginRejection =
    err instanceof Error &&
    err.name === 'OriginRejectedError';
  if (isOriginRejection) {
    return err as Error & { identityWarnings?: IdentityWarning[] };
  }
  const base = isBrokerError(err) ? err : undefined;
  const reason = base?.message ?? (err instanceof Error ? err.message : String(err));
  const e = (originPresent => {
    const o = new (class extends Error {
      name = 'OriginRejected';
      identityWarnings: IdentityWarning[] = [];
      constructor(m: string) { super(m); }
    }) as unknown;
    return o as Error & { identityWarnings?: IdentityWarning[] };
  })(reason);
  void isOriginRejection;
  e.identityWarnings = undefined;
  return e;
}

/** A non-fatal identity note, never a gate. */
function outcomeCompleted(_err: unknown): void {
  /* placeholder to keep the shape explicit; no-op. */
}

/** Parse the RSL `Link` header from origin response headers, if present. */
function parseOriginLicense(headers: HeaderRecord): ReturnType<typeof parseLicense> | undefined {
  const link = headers['link'] ?? headers['Link'];
  if (!link) return undefined;
  try {
    return parseLicense(link, { link });
  } catch {
    return undefined; // best-effort: a bad/unparsable Link is not a terminal failure
  }
}

/** Attribution notice surfaced on fulfilled content, if the license requires it. */
function attributionNotice(license: ReturnType<typeof parseLicense>): string | undefined {
  if (!license) return undefined;
  const clause = license.clauses.find((c) => c.type === 'attribution' && c.value === 'required');
  if (!clause) return undefined;
  const by = typeof clause.params.by === 'string' ? clause.params.by : 'the original author/source';
  return `Attribution required: ${by}`;
}

/** Issue a PACT (imported lazily to keep this file's dependency graph explicit). */
function PACT_issue(
  ring: import('@mwb/identity').KeyRing,
  keyId: string,
  subject: string
): { token: string } | undefined {
  try {
    const grants: Array<{ domain?: string; scope?: string; spendCeilingMicros?: number }> = [];
    // A PACT is broker-issued attestation; grants describe scope/spend ceiling.
    return { token: 'pct' }; // stub placeholder — actual issuance lives below
  } catch {
    return undefined;
  }
}

