  type PaymentRequest,
  type Quote,
  type RailAuthorization,
  type RailSettlement,
  type UrlString,
} from '@mwb/core';
import { BudgetEngine } from '@mwb/budget';
import { AuditLedger } from '@mwb/audit';
import { KeyRing, PACT } from '@mwb/identity';
import {
  deriveObligations,
  parseLicense,
  resolveStoreability,
} from '@mwb/license';

/**
 * The Metered Web Broker orchestrator — the "one contract" call.
 *
 * `Broker.fetch` composes the budget gate, the payment rail, best-effort
 * identity, the license engine, and the audit ledger into a single terminal
 * outcome. The whole thing is designed around one invariant:
 *
 *   every terminal path is one of {fulfilled, blocked, payment-required,
 *   token-rejected} — `error` status is deliberately NOT produced, because a
 *   generic failure hides the cost decision.
 *
 * Pipeline:
 *
 *   1. rail.quote(request)        → quote (the origin's price)
 *   2. budget.preflight(quote)    → `blocked`        if policy denies it
 *   3. rail.authorize(quote)      → `payment-required` if the rail can't pay
 *   4. rail.settle(auth)          → `payment-required` if settlement fails
 *   5. identity.bestEffortSign    → recorded, never a gate
 *   6. origin.fetch(…, settlement) → fulfilled / 402 → payment-required /
 *                                  403 + identity → token-rejected /
 *                                  403 no identity → blocked / else → blocked
 *   7. license.parse + derive from the origin's RSL `Link` header
 *
 * On `fulfilled` only: `BudgetEngine.recordPaid` is called exactly once, and
 * exactly one `AuditLedger` row is recorded for the `fetchId`.
 */

/** The content/SLA source the rail's settled request is sent to. */
export interface OriginResponse {
  httpStatus: number;
  headers: HeaderRecord;
  body: string;
}

export interface OriginClient {
  fetch(req: PaymentRequest): Promise<OriginResponse>;
}

export interface BrokerIdentityOptions {
  /** Subject/tenant to embed in the PACT, if a ring is present and a subject is known. */
  subject?: string;
}

export interface BrokerOptions {
  rail: PaymentRail;
  budget: BudgetEngine;
  ledger: AuditLedger;
  /** Identity vault. Absent ⇒ no identity presented (a 403 then reads as `blocked`). */
