function parseOriginLicense(headers: HeaderRecord): FetchOutcome['license'] {
  const link = headers['link'] ?? headers['Link'];
  if (!link) return undefined;
  try {
    return parseLicense(link, { link });
  } catch {
    return undefined; // best-effort: a bad Link is not a terminal failure
  }
}

/** Attribution notice surfaced on fulfilled content, if the license requires it. */
function attributionNotice(
  license: FetchOutcome['license']
): FetchOutcome['content']['attributionNotice'] {
  if (!license) return undefined;
  const clause = license.clauses.find((c) => c.type === 'attribution' && c.value === 'required');
  if (!clause) return undefined;
  const by = typeof clause.params.by === 'string' ? clause.params.by : 'the original author/source';
  return `Attribution required: ${by}`;
}
