   172	    // 1. Quote the rail — the origin's price, needed to gate on budget.
   173	    const quote = await this.rail.quote(req);
   174	
   175	    // 2. Budget gate (the first deny-gate). BudgetError is policy denial.
   176	    try {
   177	      this.budget.preflight(tenantId, quote, url);
   178	    } catch (err) {
   179	      if (err instanceof BudgetError || (err && isBrokerError(err) && err.code === 'CURRENCY_MISMATCH')) {
   180	        return this.denied('blocked', err instanceof Error ? err.message : String(err), {
   181	          url,
   182	          httpStatus: undefined,
   183	        }, tenantId);
   184	      }
   185	      throw err;
   186	    }
   187	
   188	    // 3. Authorize. A rail error here means payment could not be arranged.
   189	    const authorization: RailAuthorization = await this.rail
   190	      .authorize(req, quote)
   191	      .catch((err) => railFault(err, 'authorize', this.rail.id));
   192	
   193	    // 4. Settle — the payment commit. Record the settlement ref on the outcome.
   194	    const settlement: RailSettlement = await this.rail
   195	      .settle(req, authorization)
   196	      .catch((err) => railFault(err, 'settle', this.rail.id));
   197	
   198	    // 5. Content from the origin, settlement headers applied.
   199	    const originResp = await this.origin.fetch({
   200	      ...req,
   201	      headers: { ...req.headers, ...authorization.settlementHeaders },
   202	    });
   203	
   204	    // 6. Map the origin's HTTP answer to a terminal class.
   205	    if (!isOk(originResp.httpStatus)) {
   206	      return this.originDenied(originUrl(originResp, url), originResp.httpStatus, identity != null);
   207	    }
   208	
   209	    // fulfilled — charge the meter once and record one row.
   210	    return this.fulfilled({
   211	      url,
   212	      fetchId,
   213	      tenantId,
   214	      quote,
   215	      settlement,
   216	      identity,
   217	      origin: originResp,
   218	      startedAt,
   219	    });
   220	  }
   221	
   222	  // --- outcome builders --------------------------------------------------
   223	
   224	  private fulfilled(args: {
   225	    url: UrlString;
   226	    fetchId: string;
   227	    tenantId: string;
   228	    quote: Quote;
   229	    settlement: RailSettlement;
   230	    identity?: IdentityPresentation;
   231	    origin: OriginResponse;
   232	    startedAt: string;
   233	  }): FetchOutcome {
   234	    // 7. License — if the origin publishes RSL terms, derive obligations.
   235	    const license = parseOriginLicense(args.origin.headers);
   236	    const obligations = license ? deriveObligations(license) : [];
   237	    const storeable = license ? resolveStoreability(license) : true;
   238	
   239	    // Charge the tenant meter exactly once, on fulfillment.
   240	    this.budget.recordPaid(
   241	      args.tenantId,
   242	      { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
   243	      args.url
   244	    );
