   246	    const outcome: FetchOutcome = {
   247	      fetchId: args.fetchId,
   248	      status: 'fulfilled',
   249	      reason: 'content released after settlement',
   250	      origin: { url: String(args.url), httpStatus: args.origin.httpStatus },
   251	      content: {
   252	        body: args.origin.body,
   253	        contentType: args.origin.headers['content-type'] ?? 'application/octet-stream',
   254	        storeable,
   255	        attributionNotice: attributionNotice(license),
   256	      },
   257	      license,
   258	      obligations,
   259	      price: { unitsMicros: args.settlement.amountMicros, currency: args.settlement.currency },
   260	      quote: args.quote,
   261	      rail: args.settlement.rail,
   262	      settlementRef: args.settlement.settlementRef,
   263	      identity: identity?.keyId ? identityToPresentation(args.identity) : undefined,
   264	      tenantId: args.tenantId,
   265	      timestamps: { startedAt: args.startedAt, completedAt: this.clock.now() },
   266	    };
