   270	  }
   271	
   272	  private denied(
   273	    failureClass: FailureClass,
   274	    message: string,
   275	    info: { url: UrlString; httpStatus?: number },
   276	    tenantId: string
   277	  ): FetchOutcome {
   278	    const outcome: FetchOutcome = {
