   280	      status: 'denied',
   281	      failureClass,
   282	      reason: message,
   283	      error: { code: failureClass, message },
   284	      origin: info.httpStatus != null
   285	        ? { url: String(info.url), httpStatus: info.httpStatus }
   286	        : { url: String(info.url) },
   287	      tenantId,
   288	      timestamps: { startedAt: this.clock.now(), completedAt: this.clock.now() },
   289	    };
