   293	  }
   294	
   295	  private originDenied(url: string, httpStatus: number, identityPresent: boolean): FetchOutcome {
   296	    let failureClass: FailureClass;
   297	    let message: string;
   298	    let code: string;
   299	
   300	    if (httpStatus === 402) {
   301	      failureClass = 'payment-required';
   302	      message = 'origin still demanded payment after settlement (not obtainable)';
   303	      code = 'PAYMENT_REQUIRED';
   304	    } else if (httpStatus === 403 && identityPresent) {
   305	      failureClass = 'token-rejected';
   306	      message = 'origin rejected the presented attestation/identity (HTTP 403)';
   307	      code = 'TOKEN_REJECTED';
   308	    } else if (httpStatus === 403) {
   309	      failureClass = 'blocked';
   310	      message = 'origin blocked the request without a presented identity (HTTP 403)';
   311	      code = 'ORIGIN_BLOCKED';
   312	    } else {
   313	      failureClass = 'blocked';
   314	      message = `origin rejected the request with HTTP ${httpStatus}`;
   315	      code = 'ORIGIN_REJECTED';
   316	    }
