   318	    return this.denied(failureClass, message, { url, httpStatus });
   319	  }
   320	
   321	  // --- identity + request helpers ----------------------------------------
   322	
   323	  private paymentRequest(url: UrlString, extraHeaders?: HeaderRecord): PaymentRequest {
   324	    return {
   325	      url,
   326	      method: 'GET',
   327	      headers: {
   328	        host: new URL(String(url)).host,
   329	        'user-agent': 'metered-web-broker/0.1',
   330	        ...this.headers,
   331	        ...(extraHeaders ?? {}),
   332	      },
   333	    };
   334	  }
   335	
   336	  /**
   337	   * Best-effort identity: sign the presented headers and, when a known
   338	   * subject exists, issue a PACT. Returns undefined when no ring is present,
   339	   * no active key exists, or signing throws. Never a gate.
   340	   */
   341	  private signIdentity(req: PaymentRequest): IdentityPresentation | undefined {
   342	    if (!this.ring) return undefined;
   343	
   344	    const keyId = this.ring.active()[0]?.keyId;
   345	    if (!keyId) return undefined;
   346	
   347	    // Canonical block the origin can verify: host + date.
   348	    const signingHeaders: HeaderRecord = {
   349	      host: new URL(String(req.url)).host,
   350	      date: this.clock.now(),
   351	      ...req.headers,
   352	    };
   353	
   354	    let signedFields: string[];
   355	    try {
   356	      const signed = this.ring.sign(keyId, signingHeaders, ['host', 'date']);
   357	      signedFields = signed.signature.split('fields="')[1]!.split('"')[0]!.split(' ');
   358	    } catch (cause) {
   359	      if (cause instanceof IdentityError) return undefined;
   360	      throw cause;
   361	    }
   362	
   363	    let pactToken: string | undefined;
   364	    const subject = this.identityOpts.subject;
   365	    if (subject) {
   366	      try {
   367	        const body = {
   368	          subject,
   369	          grants: [],
   370	          iat: this.clock.now(),
   371	          iss: 'metered-web-broker',
   372	        };
   373	        pactToken = PACT.issue(this.ring, keyId, body).token;
   374	      } catch {
   375	        // Best-effort: a failed PACT issuance is ignored, not a gate.
   376	      }
   377	    }
   378	
   379	    return { keyId, algorithm: 'ed25519', signedHeaders: signedFields, timestamp: this.clock.now(), pactToken };
   380	  }
   381	
   382	  private cloneOutcome(o: FetchOutcome): FetchOutcome {
   383	    return { ...o, timestamps: { ...o.timestamps } } as FetchOutcome;
   384	  }
   385	}
   386	
   387	/** Identity presentation surfaced on a fulfilled outcome. */
   388	interface IdentityPresentation {
   389	  keyId: string;
   390	  algorithm: 'ed25519';
   391	  signedHeaders: string[];
   392	  timestamp: string;
   393	  pactToken?: string;
   394	}
   395	
   396	function identityToPresentation(x: IdentityPresentation): FetchOutcome['identity'] {
   397	  return {
   398	    keyId: x.keyId,
   399	    algorithm: x.algorithm,
   400	    signedHeaders: x.signedHeaders,
   401	    timestamp: x.timestamp,
   402	    ...(x.pactToken ? { pactToken: x.pactToken } : {}),
   403	  };
   404	}
   405	
   406	function isOk(httpStatus: number): boolean {
   407	  return httpStatus >= 200 && httpStatus < 300;
   408	}
   409	
   410	/** A best-effort origin URL for denied rows when the fetch request was dropped. */
   411	function originUrl(resp: OriginResponse, url: UrlString): string {
   412	  return headersUrl(resp) ?? String(url);
   413	}
   414	
   415	function headersUrl(resp: OriginResponse): string | undefined {
   416	  const u = resp.headers['location'] ?? resp.headers['Location'];
   417	  if (u) try { return new URL(u).toString(); } catch { return undefined; }
   418	  return undefined;
   419	}
   420	
   421	/** Wrap a rail failure as a `payment-required` fault. */
   422	function railFault(err: unknown, step: 'authorize' | 'settle', railId: string): Error {
   423	  if (isBrokerError(err)) return err;
   424	  const cause = err instanceof Error ? err : new Error(String(err));
   425	  return new RailError(`${railId}: ${step} failed`, 'RAIL_ERROR', cause, true);
   426	}
   427	
   428	/** Parse the RSL `Link` header from origin response headers, if present. */
   429	function parseOriginLicense(headers: HeaderRecord): FetchOutcome['license'] {
   430	  const link = headers['link'] ?? headers['Link'];
   431	  if (!link) return undefined;
   432	  try {
   433	    return parseLicense(link, { link });
   434	  } catch {
   435	    return undefined; // best-effort: a bad Link is not a terminal failure
   436	  }
   437	}
   438	
   439	/** Attribution notice surfaced on fulfilled content, if the license requires it. */
   440	function attributionNotice(
   441	  license: FetchOutcome['license']
   442	): FetchOutcome['content']['attributionNotice'] {
   443	  if (!license) return undefined;
   444	  const clause = license.clauses.find((c) => c.type === 'attribution' && c.value === 'required');
   445	  if (!clause) return undefined;
   446	  const by = typeof clause.params.by === 'string' ? clause.params.by : 'the original author/source';
   447	  return `Attribution required: ${by}`;
   448	}"}

