          err instanceof Error ? err.message : String(err), { url, httpStatus: undefined });
      }
      throw err;
    }

    // 3. Authorize. A rail error here means payment could not be arranged.
    const authorization: RailAuthorization = await this.rail
      .authorize(req, quote)
      .catch((err) => {
        throw railFault(err, 'authorize', this.rail.id);
      });

    // 4. Settle — the payment commit. Record the settlement ref on the outcome.
    const settlement: RailSettlement = await this.rail
      .settle(req, authorization)
      .catch((err) => {
