     7	
     8	/**
     9	 * A meter is the accounting state for a tenant's spend.
    10	 *
    11	 * Buckets:
    12	 *  - per-call  : one-shot check, not persistent here.
    13	 *  - hourly    : rolling 1-hour window for the tenant.
    14	 *  - daily     : rolling 24-hour window for the tenant.
    15	 *  - line-item : per-line-item buckets (daily + lifetime).
    16	 *
    17	 * The engine does not persist by itself. `AuditLedger` (or a durable
    18	 * implementation) persists records and rehydrates buckets if needed.
    19	 */
    20	export interface MeterState {
    21	  tenantId: string;
    22	  hourly: { windowStart: number; spentMicros: Micros };
    23	  daily: { windowStart: number; spentMicros: Micros };
    24	  lineItems: Record<string, { dailyMicros: number; lifetimeMicros: number }>;
    25	}
    26	
    27	export function emptyMeter(tenantId: string, clock: Clock): MeterState {
    28	  return {
    29	    tenantId,
    30	    hourly: { windowStart: Date.parse(clock.now()), spentMicros: 0 },
    31	    daily: { windowStart: Date.parse(clock.now()), spentMicros: 0 },
    32	    lineItems: {},
    33	  };
    34	}
    35	
    36	interface CheckResult {
    37	  ok: boolean;
    38	  code: string;
    39	  reason: string;
    40	  remainingMicros?: number;
    41	}
    42	
    43	function checkBucket(
    44	  bucketMicros: number,
    45	  ceilingMicros: number,
    46	  priceMicros: number,
    47	  label: string
    48	): CheckResult {
    49	  const remaining = ceilingMicros - bucketMicros;
    50	  if (remaining < 0) return { ok: false, code: 'CEILING_EXCEEDED', reason: `${label}: already over ceiling` };
    51	  if (priceMicros > remaining) {
    52	    return {
    53	      ok: false,
    54	      code: 'PRICE_EXCEEDS_REMAINING',
    55	      reason: `${label}: requested ${priceMicros} exceeds remaining ${remaining}`,
    56	      remainingMicros: remaining,
    57	    };
    58	  }
    59	  return { ok: true, code: 'OK', reason: '', remainingMicros: remaining };
