{"path": "packages/identity/src/ring.ts", "start_line": 1, "end_line": 323, "total_lines": 323, "content": "     1	import { KeyObject, generateKeyPairSync, sign, verify } from 'node:crypto';
     2	import { IdentityError, systemClock } from '@mwb/core';
     3	import type { Clock, HeaderRecord } from '@mwb/core';
     4	
     5	/**
     6	 * Identity & Attestation — Ed25519 key lifecycle as a first-class concern.
     7	 *
     8	 *  - issue: mint a keypair with tight expiry (default 1h, hard cap 24h)
     9	 *  - rotate: mark the current key revoked, mint the next — old key stays
    10	 *    verifiable for in-flight settlements
    11	 *  - sign: http-message-signatures style signature over selected headers
    12	 *  - PACT: broker-issued attestation token the origin can verify against
    13	 *    the public directory
    14	 *
    15	 * The directory payload below is what the broker serves at
    16	 * `/.well-known/agent-identity` so origins can look up the public key
    17	 * without a side channel.
    18	 *
    19	 * Draft-caveat discipline: build against the *patterns* of Web Bot Auth
    20	 * and PACT, not their draft field names.
    21	 */
    22	
    23	export type B64Url = string;
    24	
    25	export function b64url(bytes: Uint8Array): B64Url {
    26	  return Buffer.from(bytes).toString('base64url');
    27	}
    28	
    29	export function fromB64url(s: B64Url): Uint8Array {
    30	  return new Uint8Array(Buffer.from(s, 'base64url'));
    31	}
    32	
    33	export interface KeyPair {
    34	  /** Broker-chosen stable key id — this is what the audit trail references. */
    35	  keyId: string;
    36	  algorithm: 'ed25519';
    37	  /** 32-byte public key (JWK `x`), base64url. */
    38	  publicRaw: B64Url;
    39	  /** 32-byte seed (JWK `d`), base64url. Never leaves the broker. */
    40	  privateRaw: B64Url;
    41	  createdAt: string;
    42	  expiresAt: string;
    43	  revokedAt?: string;
    44	}
    45	
    46	export interface IssueOptions {
    47	  keyId?: string;
    48	  /** Lifetime. Default 1h; hard cap 24h (tight-expiry discipline). */
    49	  ttlMs?: number;
    50	}
    51	
    52	const MAX_TTL_MS = 24 * 3_600_000;
    53	const DEFAULT_TTL_MS = 3_600_000;
    54	
    55	/**
    56	 * The broker's identity vault. Every key the broker has ever issued, in
    57	 * memory. Keys past `expiresAt` or with `revokedAt` set refuse to sign;
    58	 * the ring keeps them so in-flight signatures still verify.
    59	 */
    60	export class KeyRing {
    61	  readonly clock: Clock;
    62	  private readonly keys = new Map<string, KeyPair>();
    63	  private counter = 0;
    64	
    65	  constructor(clock: Clock = systemClock) {
    66	    this.clock = clock;
    67	  }
    68	
    69	  /** Mint a fresh Ed25519 keypair with tight expiry. */
    70	  issue(options: IssueOptions = {}): KeyPair {
    71	    const now = this.clock.now();
    72	    const nowMs = Date.parse(now);
    73	    const ttl = Math.min(Math.max(1_000, options.ttlMs ?? DEFAULT_TTL_MS), MAX_TTL_MS);
    74	    const { publicKey, privateKey } = generateKeyPairSync('ed25519');
    75	    const pubJwk = publicKey.export({ format: 'jwk' }) as JsonWebKey;
    76	    const privJwk = privateKey.export({ format: 'jwk' }) as JsonWebKey;
    77	    if (!pubJwk.x || !privJwk.d) {
    78	      throw new IdentityError('failed to export Ed25519 JWK', 'IDENTITY_EXPORT');
    79	    }
    80	    this.counter += 1;
    81	    const keyId = options.keyId ?? `key_${this.counter.toString(36)}_${nowMs.toString(36)}`;
    82	    if (this.keys.has(keyId)) {
    83	      throw new IdentityError(`keyId already in use: ${keyId}`, 'IDENTITY_DUPLICATE');
    84	    }
    85	    const kp: KeyPair = {
    86	      keyId,
    87	      algorithm: 'ed25519',
    88	      publicRaw: b64url(fromB64url(pubJwk.x as string)),
    89	      privateRaw: b64url(fromB64url(privJwk.d as string)),
    90	      createdAt: now,
    91	      expiresAt: new Date(nowMs + ttl).toISOString(),
    92	    };
    93	    this.keys.set(keyId, kp);
    94	    return kp;
    95	  }
    96	
    97	  /**
    98	   * Rotate: mark the current active key revoked, mint a fresh one. The old
    99	   * key remains verifiable until the caller drops it — that is what lets
   100	   * in-flight settlements close out cleanly.
   101	   */
   102	  rotate(options: IssueOptions = {}): { previous?: KeyPair; next: KeyPair } {
   103	    const current = this.active().sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];
   104	    if (current) current.revokedAt = this.clock.now();
   105	    const next = this.issue(options);
   106	    return { previous: current, next };
   107	  }
   108	
   109	  get(keyId: string): KeyPair {
   110	    const kp = this.keys.get(keyId);
   111	    if (!kp) throw new IdentityError(`unknown key: ${keyId}`, 'IDENTITY_UNKNOWN');
   112	    return kp;
   113	  }
   114	
   115	  all(): KeyPair[] {
   116	    return [...this.keys.values()];
   117	  }
   118	
   119	  active(): KeyPair[] {
   120	    const now = Date.parse(this.clock.now());
   121	    return this.all().filter((k) => !k.revokedAt && Date.parse(k.expiresAt) >= now);
   122	  }
   123	
   124	  /**
   125	   * Sign a canonicalized header block.
   126	   *
   127	   * Canonicalization: lowercase header names, lexicographic order, one
   128	   * `name: value` per line, joined with `\n`, trailing `\n`. This is the
   129	   * *pattern* of http-message-signatures; the exact wire form tracks
   130	   * whatever draft the origin validates against.
   131	   *
   132	   * Returns:
   133	   *  - `signature`: the wire header value to attach
   134	   *  - `message`: the canonical signing string (for replay/debug)
   135	   *  - `signedAt`: broker timestamp
   136	   */
   137	  sign(
   138	    keyId: string,
   139	    headers: HeaderRecord,
   140	    signedFields: string[] = ['host', 'date']
   141	  ): { signature: string; message: string; signedAt: string } {
   142	    const kp = this.get(keyId);
   143	    const now = this.clock.now();
   144	    if (kp.revokedAt) throw new IdentityError(`key revoked: ${keyId}`, 'IDENTITY_REVOKED');
   145	    if (Date.parse(kp.expiresAt) < Date.parse(now)) {
   146	      throw new IdentityError(`key expired: ${keyId}`, 'IDENTITY_EXPIRED');
   147	    }
   148	
   149	    const fields = signedFields.map((f) => f.toLowerCase()).sort();
   150	    const normed = normHeaders(headers);
   151	    const lines = fields.map((f) => {
   152	      const v = normed.get(f);
   153	      if (v === undefined) throw new IdentityError(`missing header to sign: ${f}`, 'IDENTITY_FIELD');
   154	      return `${f}: ${v}`;
   155	    });
   156	    const message = lines.join('\n') + '\n';
   157	
   158	    const seed = fromB64url(kp.privateRaw);
   159	    const keyObject = KeyObject.fromJwk({
   160	      kty: 'OKP',
   161	      crv: 'Ed25519',
   162	      d: kp.privateRaw,
   163	    } as JsonWebKey);
   164	    const sigBytes = Buffer.from(sign(null, Buffer.from(message, 'utf8'), keyObject));
   165	    const sig = b64url(new Uint8Array(sigBytes));
   166	    const signature = `keyId="${keyId}";algorithm="ed25519";fields="${fields.join(' ')}";signature="${sig}"`;
   167	    return { signature, message, signedAt: now };
   168	  }
   169	
   170	  /** Verify a signature produced by this ring. */
   171	  verify(keyId: string, message: string, sigB64url: B64Url): boolean {
   172	    try {
   173	      const kp = this.get(keyId);
   174	      const keyObject = KeyObject.fromJwk({
   175	        kty: 'OKP',
   176	        crv: 'Ed25519',
   177	        x: kp.publicRaw,
   178	      } as JsonWebKey);
   179	      return verify(null, Buffer.from(message, 'utf8'), keyObject, Buffer.from(fromB64url(sigB64url)));
   180	    } catch {
   181	      return false;
   182	    }
   183	  }
   184	
   185	  /**
   186	   * Directory the broker serves at `/.well-known/agent-identity`. Only
   187	   * active keys appear, sorted by keyId for stable diffs.
   188	   */
   189	  directory(): {
   190	    format: 'agent-identity-directory';
   191	    agentIdentity: Array<{ keyId: string; alg: 'Ed25519'; pubkey: string; expires: string }>;
   192	  } {
   193	    return {
   194	      format: 'agent-identity-directory',
   195	      agentIdentity: this.active()
   196	        .slice()
   197	        .sort((a, b) => a.keyId.localeCompare(b.keyId))
   198	        .map((k) => ({
   199	          keyId: k.keyId,
   200	          alg: 'Ed25519' as const,
   201	          pubkey: k.publicRaw,
   202	          expires: k.expiresAt,
   203	        })),
   204	    };
   205	  }
   206	}
   207	
   208	function normHeaders(headers: HeaderRecord): Map<string, string> {
   209	  const out = new Map<string, string>();
   210	  for (const [k, v] of Object.entries(headers ?? {})) out.set(k.toLowerCase(), v);
   211	  return out;
   212	}
   213	
   214	/**
   215	 * A PACT is a broker-issued, key-signed attestation token. Wire format is
   216	 * intentionally minimal:
   217	 *
   218	 *   <base64url(json of claims)> . <keyId> . <base64url(signature)>
   219	 *
   220	 * where the signature covers `<claimsBytes>` exactly (so origin replays
   221	 * the same bytes it received, and the keyId selects the ring entry). When
   222	 * the PACT spec stabilizes, this token shape stays — only the payload
   223	 * inside changes.
   224	 */
   225	export class PACT {
   226	  static issue(ring: KeyRing, keyId: string, claims: Record<string, unknown>): {
   227	    token: string;
   228	    message: string;
   229	    signedAt: string;
   230	  } {
   231	    const body = JSON.stringify(claims);
   232	    const b64 = Buffer.from(body, 'utf8').toString('base64url');
   233	    const sigB64url = b64url(signPactBody(body, ring, keyId));
   234	    return {
   235	      token: `${b64}.${keyId}.${sigB64url}`,
   236	      message: body,
   237	      signedAt: ring.clock.now(),
   238	    };
   239	  }
   240	
   241	  static parse(token: string): { claims: Record<string, unknown>; keyId: string; signature: B64Url; body: string } {
   242	    const parts = token.split('.');
   243	    if (parts.length !== 3) throw new IdentityError('malformed PACT token (expected 3 parts)', 'PACT_MALFORMED');
   244	    const [bodyB64, keyId, signature] = parts as [B64Url, string, B64Url];
   245	    const body = Buffer.from(bodyB64, 'base64url').toString('utf8');
   246	    let claims: Record<string, unknown>;
   247	    try {
   248	      claims = JSON.parse(body) as Record<string, unknown>;
   249	    } catch (cause) {
   250	      throw new IdentityError('PACT claims are not valid JSON', 'PACT_CLAIMS', cause);
   251	    }
   252	    return { claims, keyId, signature, body };
   253	  }
   254	
   255	  static verify(token: string, ring: KeyRing): { valid: boolean; reason?: string; claims?: Record<string, unknown> } {
   256	    const { claims, keyId, signature, body } = PACT.parse(token);
   257	    if (new Date(claims.expiresAt as string).getTime() < Date.parse(ring.clock.now())) {
   258	      return { valid: false, reason: 'pact-expired', claims };
   259	    }
   260	    const ok = signPactVerify(body, ring, keyId, signature);
   261	    if (!ok) return { valid: false, reason: 'signature-mismatch', claims };
   262	    return { valid: true, claims };
   263	  }
   264	}
   265	
   266	/** Sign the exact bytes of a PACT body (not a header canonicalization). */
   267	function signPactBody(body: string, ring: KeyRing, keyId: string): Uint8Array {
   268	  const kp = ring.get(keyId);
   269	  const keyObject = KeyObject.fromJwk({
   270	    kty: 'OKP',
   271	    crv: 'Ed25519',
   272	    d: kp.privateRaw,
   273	  } as JsonWebKey);
   274	  return new Uint8Array(sign(null, Buffer.from(body, 'utf8'), keyObject));
   275	}
   276	
   277	function signPactVerify(body: string, ring: KeyRing, keyId: string, sigB64url: B64Url): boolean {
   278	  try {
   279	    const kp = ring.get(keyId);
   280	    const keyObject = KeyObject.fromJwk({
   281	      kty: 'OKP',
   282	      crv: 'Ed25519',
   283	      x: kp.publicRaw,
   284	    } as JsonWebKey);
   285	    return verify(null, Buffer.from(body, 'utf8'), keyObject, Buffer.from(fromB64url(sigB64url)));
   286	  } catch {
   287	    return false;
   288	  }
   289	}
   290	
   291	// PACT helpers — small indirections so KeyRing stays readable. The `keyId`
   292	// is already on the ring, so these resolve via the ring.
   293	function require_ring_sign(_ring: KeyRing): { signature: string } {
   294	  return { signature: '' };
   295	}
   296	
   297	function signMessage(keyId: string, message: string, ring: KeyRing): { signature: B64Url } {
   298	  const kp = ring.get(keyId);
   299	  const keyObject = KeyObject.fromJwk({
   300	    kty: 'OKP',
   301	    crv: 'Ed25519',
   302	    d: kp.privateRaw,
   303	  } as JsonWebKey);
   304	  return { signature: b64url(new Uint8Array(sign(null, Buffer.from(message, 'utf8'), keyObject))) };
   305	}
   306	
   307	/** Convenience: issue a common-claims PACT with standard expiry. */
   308	export function issuePact(
   309	  ring: KeyRing,
   310	  keyId: string,
   311	  subject: string,
   312	  grants?: Array<{ domain?: string; scope?: string; spendCeilingMicros?: number }>
   313	): { token: string; body: string } {
   314	  const nowMs = Date.parse(ring.clock.now());
   315	  const body = {
   316	    subject,
   317	    grants: grants ?? [],
   318	    iat: new Date(nowMs).toISOString(),
   319	    exp: new Date(Math.min(nowMs + 15 * 60_000, Date.parse(ring.get(keyId).expiresAt))).toISOString(),
   320	    iss: 'metered-web-broker',
   321	  };
   322	  return PACT.issue(ring, keyId, body);
   323	}"}

