{"content": "import { describe, expect, it } from 'vitest';
import {
  AuditLedger,
  reconcile,
  summarize,
} from '@mwb/audit';
import { BudgetEngine, defaultPolicy } from '@mwb/budget';
import { InMemoryRail } from '@mwb/rails';
import { KeyRing } from '@mwb/identity';
import { frozenClock, makeFetchId, makeSettlementRef } from '@mwb/core';
import type { OriginResponse, TerminalKind } from '@mwb/gateway';
import { Broker } from '@mwb/gateway';

const clock = frozenClock();

const PRICE = 5000; // 5000 micros
const URL = 'https://api.example.com/data';

/** A minimal origin that returns whatever status we configure. */
function origin(response: Partial<OriginResponse> = {}): OriginResponse {
  return {
    httpStatus: 200,
    headers: {},
    body: '<html>ok</html>',
    ...response,
  };
}

function make({
  price = PRICE,
  failureMode = 'none',
  currency,
  ring = false,
  origin: resp = origin(),
}: {
  price?: number;
  failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
  currency?: string;
  ring?: boolean;
  origin?: OriginResponse;
} = {}) {
  const budget = new BudgetEngine({ policy: defaultPolicy(clock), clock });
  const ledger = new AuditLedger({ clock });
  const rail = new InMemoryRail({
    id: 'x402',
    priceMicros: price,
    currency: currency ?? defaultPolicy(clock).currency,
    clock,
    settlementSeed: 'seed',
    failureMode,
  });
  const opts: ConstructorParameters<typeof Broker>[0] = {
    rail,
    budget,
    ledger,
    origin: { fetch: () => Promise.resolve(resp) },
    clock,
  };
  if (ring) opts.ring = new KeyRing(clock);
  return { budget, ledger, rail, opts };
}

function run(opts: ConstructorParameters<typeof Broker>[0], params?: { fetchId?: string; tenantId?: string }) {
  const b = new Broker(opts);
  const f = params?.fetchId ?? makeFetchId();
  return {
    broker: b,
    outcome: b.fetch({ url: URL, fetchId: f, tenantId: params?.tenantId }),
  };
}

describe('Broker.fetch — fulfilled', () => {
  it('charges the meter once, records exactly one row, and reconciles', async () => {
    const { ledger, budget, rail } = make();
    const { broker, outcome } = await run({ rail, budget, ledger, origin: origin() });

    const o = await outcome;
    expect(o.status).toBe('fulfilled');
    expect(o.failureClass).toBeUndefined();
    expect(o.tenantId).toBe('default');
    expect(o.license).toBeUndefined();

    // exactly one row, and the idempotent fetch returns the same one
    expect(ledger.entries.length).toBe(1);
    expect(broker.rowFor(o.fetchId)).toBe(ledger.entries[0]);
    expect(await broker.outcomeFor(o.fetchId)).toEqual(o);

    // charge recorded once
    expect(budget.byTenant('default').length).toBe(1);
    const settled = ledger.entries[0];
    expect(settled.priceMicros).toBe(PRICE);
    expect(settled.currency).toBe(defaultPolicy(clock).currency);
    expect(settled.rail).toBe('x402');
    expect(settled.settlementRef).toBeTruthy();

    const rep = reconcile(ledger.entries);
    expect(rep.ok).toBe(true);
    expect(rep.problems).toEqual([]);
  });

  it('records identity on a fulfilled outcome when a ring is present', async () => {
    const { ledger, budget, rail } = make({ ring: true });
    const { outcome } = await run({ rail, budget, ledger, origin: origin() });
    const o = await outcome;
    expect(o.identity?.keyId).toBeTruthy();
    expect(o.identity?.pactToken).toBeTruthy();
    expect(ledger.entries[0].keyId).toBe(o.identity!.keyId);
  });

  it('derives obligations and an attribution notice from a published license', async () => {
    const link = '<https://licenses.example/r/73>; rel="type:license-terms"';
    const resp = origin({
      headers: { link, 'content-type': 'text/html' },
      body: '<html>with terms</html>',
    });
    const { ledger, rail, budget } = make({ origin: resp });
    const { outcome } = await run({ rail, budget, ledger, origin: resp });
    const o = await outcome;

    expect(o.license).toBeDefined();
    expect(o.license?.id).toBe('/r/73');
    expect(Array.isArray(o.obligations)).toBe(true);
    expect(o.content?.contentType).toBe('text/html');
  });
});

describe('Broker.fetch — blocked (budget is the first gate)', () => {
  it('maps a BudgetError policy denial to blocked', async () => {
    const policy = {
      ...defaultPolicy(clock),
      perCallCeilingMicros: 100, // quote is 5000 → over ceiling
    };
    const budget = new BudgetEngine({ policy, clock });
    const ledger = new AuditLedger({ clock });
    const rail = new InMemoryRail({ id: 'x402', priceMicros: 5000, currency: policy.currency, clock });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const o = await broker.fetch({ url: URL });

    expect(o.status).toBe('denied');
    expect(o.failureClass).toBe('blocked');
    expect(o.error.code).toBe('blocked');
    // never reached the origin
    expect(o.origin?.httpStatus).toBeUndefined();
    expect(ledger.entries.length).toBe(1);
    expect(reconcile(ledger.entries).checks.deniedHasFailureClass).toBe(true);
  });

  it('maps a currency mismatch to blocked', async () => {
    const { rail, budget, ledger } = make({ currency: 'EUR' });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('blocked');
    expect(ledger.entries[0].status).toBe('denied');
  });

  it('maps a non-2xx origin (no identity) to blocked', async () => {
    const { rail, budget, ledger } = make({ origin: origin({ httpStatus: 500 }) });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin({ httpStatus: 500 })) } });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('blocked');
    expect(o.origin?.httpStatus).toBe(500);
  });

  it('maps a 403-without-identity origin to blocked', async () => {
    const resp = origin({ httpStatus: 403 });
    const broker = new Broker({
      rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock }),
      budget: new BudgetEngine({ policy: defaultPolicy(clock), clock }),
      ledger: new AuditLedger({ clock }),
      origin: { fetch: () => Promise.resolve(resp) },
    });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('blocked');
  });
});

describe('Broker.fetch — payment-required', () => {
  it('maps authorize failure to payment-required', async () => {
    const { rail, budget, ledger } = make({ failureMode: 'authorize' });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('payment-required');
    expect(o.error.code).toBe('payment-required');
  });

  it('maps settle failure to payment-required', async () => {
    const { rail, budget, ledger } = make({ failureMode: 'settle' });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('payment-required');
  });

  it('maps a 402 origin to payment-required', async () => {
    const resp = origin({ httpStatus: 402 });
    const broker = new Broker({
      rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock }),
      budget: new BudgetEngine({ policy: defaultPolicy(clock), clock }),
      ledger: new AuditLedger({ clock }),
      origin: { fetch: () => Promise.resolve(resp) },
    });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('payment-required');
    expect(o.origin?.httpStatus).toBe(402);
  });
});

describe('Broker.fetch — token-rejected', () => {
  it('maps a 403 origin that rejected presented identity to token-rejected', async () => {
    const resp = origin({ httpStatus: 403 });
    const broker = new Broker({
      rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock }),
      budget: new BudgetEngine({ policy: defaultPolicy(clock), clock }),
      ledger: new AuditLedger({ clock }),
      ring: new KeyRing(clock),
      identity: { subject: 'tenant-a' },
      origin: { fetch: () => Promise.resolve(resp) },
    });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('token-rejected');
    expect(o.origin?.httpStatus).toBe(403);
  });
});

describe('Broker.fetch — idempotency', () => {
  it('returns the cached outcome and re-quotes/re-setstles only once', async () => {
    const { ledger, budget, rail } = make();
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const f = makeFetchId();

    const a = await broker.fetch({ url: URL, fetchId: f });
    const b = await broker.fetch({ url: URL, fetchId: f });

    expect(broker.rowFor(f)).toBe(ledger.entries[0]);
    expect(ledger.entries.length).toBe(1);
    expect(budget.byTenant('default').length).toBe(1);
    expect(a.fetchId).toBe(b.fetchId);
    expect(a.status).toBe(b.status);
  });
});

describe('Broker.fetch — terminal-class invariant', () => {
  it('every denied outcome is one of the three failure classes', async () => {
    const cases: Array<{ name: string; build: () => Broker }> = [
      { name: 'policy blocked', build: () => {
        const budget = new BudgetEngine({ policy: { ...defaultPolicy(clock), perCallCeilingMicros: 100 }, clock });
        return new Broker({ rail: new InMemoryRail({ id: 'x402', priceMicros: 5000, currency: defaultPolicy(clock).currency, clock }), budget, ledger: new AuditLedger({ clock }), origin: { fetch: () => Promise.resolve(origin()) } });
      }},
      { name: 'currency blocked', build: () => {
        const budget = new BudgetEngine({ policy: defaultPolicy(clock), clock });
        return new Broker({ rail: new InMemoryRail({ id: 'x402', priceMicros: 5000, currency: 'EUR', clock }), budget, ledger: new AuditLedger({ clock }), origin: { fetch: () => Promise.resolve(origin()) } });
      }},
      { name: 'auth required', build: () => new Broker({ rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock, failureMode: 'authorize' }), budget: new BudgetEngine({ policy: defaultPolicy(clock), clock }), ledger: new AuditLedger({ clock }), origin: { fetch: () => Promise.resolve(origin()) } }) },
      { name: 'settle required', build: () => new Broker({ rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock, failureMode: 'settle' }), budget: new BudgetEngine({ policy: defaultPolicy(clock), clock }), ledger: new AuditLedger({ clock }), origin: { fetch: () => Promise.resolve(origin()) } }) },
      { name: 'origin 402', build: () => new Broker({ rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock }), budget: new BudgetEngine({ policy: defaultPolicy(clock), clock }), ledger: new AuditLedger({ clock }), origin: { fetch: () => Promise.resolve(origin({ httpStatus: 402 })) } }) },
      { name: 'origin 403+identity', build: () => new Broker({ rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock }), budget: new BudgetEngine({ policy: defaultPolicy(clock), clock }), ledger: new AuditLedger({ clock }), ring: new KeyRing(clock), origin: { fetch: () => Promise.resolve(origin({ httpStatus: 403 })) } }) },
      { name: 'origin 403 no-identity', build: () => new Broker({ rail: new InMemoryRail({ id: 'x402', priceMicros: PRICE, clock }), budget: new BudgetEngine({ policy: defaultPolicy(clock), clock }), ledger: new AuditLedger({ clock }), origin: { fetch: () => Promise.resolve(origin({ httpStatus: 403 })) } }) },
    ];

    const valid: TerminalKind[] = ['fulfilled', 'blocked', 'payment-required', 'token-rejected'];
    for (const c of cases) {
      const o = await c.build().fetch({ url: URL });
      expect(valid).toContain(o.failureClass ?? 'fulfilled');
      if (o.status === 'denied') expect(o.failureClass).toBeDefined();
      // and the ledger reconciles: no denied row lacks a class
      const rep = reconcile(c.build().constructor === Broker ? new AuditLedger({ clock }).entries : []);
      expect(rep.ok).toBe(true);
