  /** Every terminal path must land on one of the three classes (or fulfilled), and
   *  reconcile the recorded ledger cleanly — no denied row ever lacks a class. */
  it('every denied path is one of the three failure classes and reconciles', async () => {
    const valid: TerminalKind[] = ['fulfilled', 'blocked', 'payment-required', 'token-rejected'];

    const makeBroker = (cfg: {
      origin?: OriginResponse;
      failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
      currency?: string;
      ceiling?: number;
      ring?: boolean;
    } = {}) => {
      const budget = new BudgetEngine({
        policy: { ...defaultPolicy(clock), ...(cfg.ceiling != null ? { perCallCeilingMicros: cfg.ceiling } : {}) },
        clock,
      });
      const ledger = new AuditLedger({ clock });
      const rail = new InMemoryRail({
        id: 'x402',
        priceMicros: cfg.ceiling != null ? cfg.ceiling + 5000 : PRICE,
        currency: cfg.currency,
        clock,
        failureMode: cfg.failureMode,
      });
      const broker = new Broker({
        rail, budget, ledger,
        ...(cfg.ring ? { ring: new KeyRing(clock) } : {}),
        origin: { fetch: () => Promise.resolve(cfg.origin ?? origin()) },
      });
      return { broker, ledger };
    };

    const configs = [
      makeBroker({ ceiling: 100 }),           // budget over ceiling → blocked
      makeBroker({ currency: 'EUR' }),         // currency mismatch → blocked
      makeBroker({ failureMode: 'authorize' }), // → payment-required
      makeBroker({ failureMode: 'settle' }),    // → payment-required
      makeBroker({ origin: origin({ httpStatus: 402 }) }), // → payment-required
      makeBroker({ origin: origin({ httpStatus: 403 }), ring: true }), // identity present → token-rejected
      makeBroker({ origin: origin({ httpStatus: 403 }) }),       // no identity → blocked
      makeBroker(),                            // fulfilled
    ];

    for (const { broker, ledger } of configs) {
      const o = await broker.fetch({ url: URL });
      expect(valid).toContain(o.failureClass ?? 'fulfilled');
      if (o.status === 'denied') expect(o.failureClass).toBeDefined();
      const rep = reconcile(ledger.entries);
      expect(rep.ok).toBe(true);
      expect(rep.problems).toEqual([]);
    }
  });
