describe('Broker.fetch — blocked (budget is the first gate)', () => {
  it('maps a BudgetError policy denial to blocked', async () => {
    const policy = { ...defaultPolicy(clock), perCallCeilingMicros: 100 }; // quote is 5000 → over ceiling
    const budget = new BudgetEngine({ policy, clock });
    const ledger = new AuditLedger({ clock });
    const rail = new InMemoryRail({ id: 'x402', priceMicros: 5000, currency: policy.currency, clock });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
