    expect(o.failureClass).toBe('blocked');
    expect(o.error.code).toBe('blocked');
    expect(o.origin?.httpStatus).toBeUndefined(); // never reached the origin
    expect(ledger.entries.length).toBe(1);
    expect(reconcile(ledger.entries).checks.deniedHasFailureClass).toBe(true);
