    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin()) } });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('blocked');
    expect(ledger.entries[0].status).toBe('denied');
  });

