    const { rail, budget, ledger } = make({ origin: origin({ httpStatus: 500 }) });
    const broker = new Broker({ rail, budget, ledger, origin: { fetch: () => Promise.resolve(origin({ httpStatus: 500 })) } });
    const o = await broker.fetch({ url: URL });
    expect(o.failureClass).toBe('blocked');
