   345	  /**
   346	   * Best-effort identity: sign the presented headers and, when a known
   347	   * subject exists, issue a PACT. Returns undefined when no ring is present,
   348	   * no active key exists, or signing throws. Never a gate.
   349	   */
   350	  private signIdentity(req: PaymentRequest): IdentityPresentation | undefined {
   351	    if (!this.ring) return undefined;
   352	
   353	    const keyId = this.ring.active()[0]?.keyId;
   354	    if (!keyId) return undefined;
   355	
   356	    // Canonical block the origin can verify: host + date.
   357	    const signingHeaders: HeaderRecord = {
   358	      host: new URL(String(req.url)).host,
   359	      date: this.clock.now(),
   360	      ...req.headers,
   361	    };
   362	
   363	    let signedFields: string[];
   364	    try {
   365	      const signed = this.ring.sign(keyId, signingHeaders, ['host', 'date']);
   366	      signedFields = signed.signature.split('fields="')[1]!.split('"')[0]!.split(' ');
   367	    } catch (cause) {
   368	      if (cause instanceof IdentityError) return undefined;
   369	      throw cause;
   370	    }
   371	
   372	    let pactToken: string | undefined;
   373	    const subject = this.identityOpts.subject;
   374	    if (subject) {
   375	      try {
   376	        const body = {
   377	          subject,
   378	          grants: [],
   379	          iat: this.clock.now(),
   380	          iss: 'metered-web-broker',
   381	        };
   382	        pactToken = PACT.issue(this.ring, keyId, body).token;
   383	      } catch {
   384	        // Best-effort: a failed PACT issuance is ignored, not a gate.
   385	      }
   386	    }
   387	
   388	    return { keyId, algorithm: 'ed25519', signedHeaders: signedFields, timestamp: this.clock.now(), pactToken };
   389	  }
